  void init(long long n) {
    for (long long i = 0; i < n; i++) {
      parent.push_back(i);
      sizes.push_back(1);
    }
  }
  long long root(long long n) {
    if (parent[n] == n) return n;
    return parent[n] = root(parent[n]);
  }
  void unite(long long a, long long b) {
    parent[b] = a;
    sizes[root(a)] += sizes[root(b)];
  }
  bool is_united(long long a, long long b) {return (root(a) == root(b));}
};

