        ranks[i] = 0;
    }
}

int findset(int x){
    if (parent[x] == x) return x;
    parent[x] = findset(parent[x]); // path compression
    return parent[x];
}

bool sameset(int x, int y){
    return findset(x) == findset(y);
}

void mergeset(int x, int y){
    x = findset(x);
    y = findset(y);
    if(ranks[x] > ranks[y]){
        parent[y] = x;
    } else { //ranks[x] <= ranks[y]
        parent[x] = y;
        if (ranks[x] == ranks[y]){
            ranks[y]++;
        }
    }
}

