class UnionFind {
public:
  UnionFind(int n) {
    r.resize(n, 0);
    p.resize(n, -1);
  }
  void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return ;
    if (r[a] > r[b]) {
      p[a] += p[b];
      p[b] = a;
    } else {
      p[b] += p[a];
      p[a] = b;
      if(r[a] == r[b]) r[b]++;
    }
    return ;
  }
  int find(int a) {
    return (p[a] < 0) ? a : p[a] = find(p[a]);
  }
  bool same(int a, int b) {
    return find(a) == find(b);
  }
  size_t size(int n) {
    return -p[find(n)];
  }
private:
  vector<int> r, p;
};

int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.setf(ios_base::fixed);
  cout.precision(15);

  int n, m;
  while (cin >> n >> m) {
    UnionFind uf(n+m);
    for (int i = 0; i < n; ++i) {
      int k;
      cin >> k;
      vec<int> v(k);
      cin >> v;
      each (j, v) uf.unite(i, n + j - 1);
    }
    for (int i = 0; i < n+m; ++i) {
      uf.find(i);
    }

    bool f = true;
    for (int i = 0; i < n; ++i) {
      f = f && uf.same(0, i);
    }
    cout << (f ? "YES" : "NO") << endl;
  }

  return 0;
}

