struct UnionFind {
    int n; // id : 0...n-1
    vector<int> par;

    UnionFind(int n = 0) : n(n), par(n,-1) { }
    int root(int x) {
        assert(0 <= x && x < n);
        return par[x] < 0 ? x : par[x] = root(par[x]);
    }
    bool unite(int x, int y) {
        x = root(x), y = root(y);
        if (x == y) return false;
        if (par[x] < par[y]) swap(x,y);
        par[y] += par[x];
        par[x] = y;
        return true;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return -par[root(x)]; }
};

int32_t main() {
    int n,m; cin >> n >> m;
    UnionFind uf(n+m);
    rep (i,n) {
        int k; cin >> k;
        rep (j,k) {
            int L; cin >> L; L--;
            uf.unite(i,n+L);
        }
    }
    int r = uf.root(0);
    rep (i,n) if (uf.root(i) != r) quit("NO");
    quit("YES");
}

