#include        <bits/stdc++.h>
using namespace std;

int	get_g(int i, vector<int> &grp) {
	if (i==grp.at(i)) return i;
	return get_g(grp.at(i), grp);
}

int     main() {
	int N, M;
	cin >>N >>M;
	vector<vector<int>> L(N+1);
	for (int i=1; i<=N; i++) {
		int K;
		cin >>K;
		for (int j=0; j<K; j++) {
			int LL;
			cin >>LL;
			LL +=100000;
			// Member: i speaks Language LL
			L.at(i).push_back(LL);
		}
	}
	// NN: Number of nodes
	// M: Number of links
	int NN=200000;
	// Data store
	// p: Original value for each position
	// grp: Group#
	// grp_depth: Steps to the group root
	//vector<int> p(NN+1, 0);
	vector<int> grp(NN+1, 0);
	vector<int> grp_depth(NN+1, 0);
	// Read data for each node
	// Initialize group# as each own
	for (int i=1; i<=NN; i++) {
		grp.at(i)=i;
	}
	// Grouping
	for (int i=1; i<=N; i++) {
		int xx=i;
		for (int j=0; j<L.at(i).size(); j++) {
			int yy=L.at(i).at(j);
			xx=get_g(xx, grp);
			yy=get_g(yy, grp);
			// Already in same group, do nothing
			if (xx==yy) continue;
			// Put into one group
			if (grp_depth.at(xx)==grp_depth.at(yy)) {
				// Groups have same height
				// Merge into less-number-group
				grp.at(max(xx, yy)) = get_g(min(xx, yy), grp);
				grp_depth.at(min(xx, yy))++;
			} else if (grp_depth.at(xx)>grp_depth.at(yy)) {
				// x is higher
				// Merge into x so that the hight will not increase
				// (height for y will be +1)
				grp.at(yy) = xx;
			} else
				// y is higher
				// Merget into y
				grp.at(xx) = yy;
		}
	}
	for (int i=2; i<=N; i++) {
		if (grp.at(1)==grp.at(i))
			continue;
		else {
			cout <<"NO" <<endl;
			return 0;
		}
	}
	cout <<"YES" <<endl;
	return 0;
};

