    used[i] = true;
    rep(j, 0, K) {
      int L; cin >> L; L--;
      uf.connect(i, N + L);
      used[N+L] = true;
    }
  }
  set<int> st;
  rep(i, 0, N + M) if(used[i]) st.insert(uf.root(i));
  return st.size() == 1;
}

