    rank.resize(n,0);
    pars.resize(n);
    for(int i=0;i<n;i++)pars[i]=i;
  }
  int root(int x){
    if(pars[x]!=x)return root(pars[x]);
    else return x;
  }
  bool same(int x,int y){
    return root(x)==root(y);
  }
  void unite(int x,int y){
    x=root(x);
    y=root(y);
    if(x==y)return;
    if(rank[x]>rank[y]){
      pars[y]=x;
    }
    else{
      pars[x]=y;
      if(pars[x]==pars[y])rank[x]++;
    }
  }
};

