class UnionFind {
 public:
  UnionFind(int n) : n_(n) { Initialize(); }
  int GetRoot(int x);
  bool IsSame(int x, int y);
  void Unite(int x, int y);

 private:
  const int n_;
  std::vector<int> parent_;
  std::vector<int> rank_;
  void Initialize();
};

void UnionFind::Initialize() {
  parent_.assign(n_, -1);
  rank_.assign(n_, 0);
}

int UnionFind::GetRoot(int x) {
  if (parent_[x] == -1)
    return x;
  else
    return parent_[x] = GetRoot(parent_[x]);
}

bool UnionFind::IsSame(int x, int y) { return GetRoot(x) == GetRoot(y); }

void UnionFind::Unite(int x, int y) {
  x = GetRoot(x);
  y = GetRoot(y);
  if (x == y) return;
  if (rank_[x] < rank_[y]) std::swap(x, y);
  if (rank_[x] == rank_[y]) ++rank_[x];
  parent_[y] = x;
  return;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n, m; cin >> n >> m;
  UnionFind uf(n + m);

  for (int i = 0; i < n; ++i) {
    int k; cin >> k;
    for (int j = 0; j < k; ++j) {
      int l; cin >> l; --l;
      uf.Unite(i, n + l);
    }
  }

  for (int i = 0; i < n - 1; ++i) {
    if (!uf.IsSame(i, i + 1)) {
      cout << "NO" << endl;
      return 0;
    }
  }

  cout << "YES" << endl;

  return 0;
}

