            lang--;
            g.addEdge(i, n+lang, 1);
        }
    }
    auto dij = Dijkstra(g, 0);
    const long long WeightINF = numeric_limits<long long>::max()/2-1;
    bool ok = true;
    for(ll i=0; i<n; i++) if(dij[i] == WeightINF) ok = false;
    ok ? YES() : NO();
}

