const int MAX_N = 10000;
class UnionFind {
private:
    int union_size[MAX_N];
    int rank[MAX_N];

public:
    int par[MAX_N];

    void init(int n)
    {
        for (int i=0; i<n; i++) {
            par[i]=i;
            rank[i]=0;
            union_size[i] = 1;
        }
    }

    // 木の根を求める
    int find(int x)
    {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    // xとyの属する集合を併合する
    void merge(int x, int y)
    {
        x = find(x);
        y = find(y);
        if (x == y) return;

        union_size[x] += union_size[y];
        union_size[y] = union_size[x];

        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
    }

    // xとyが同じ集合に属するか判定する
    bool same(int x, int y)
    {
        return find(x) == find(y);
    }

    // x が含まれる集合の要素数を返す
    int getUnionSize(int x)
    {
        return union_size[find(x)];
    }
};

int main()
{
    ios::sync_with_stdio(false);

    map<int, set<int>> can;

    int N, M;
    cin >> N >> M;
    rep(i, N) {
        int K; cin >> K;
        rep(j, K) {
            int L;
            cin >> L;
            L--;
            can[L].insert(i);
        }
    }

    UnionFind UF;
    UF.init(N);

    rep(i, M) {
        if (can[i].size() == 0) continue;
        for (auto u : can[i]) {
            UF.merge(i, u);
        }
    }

    cout << (UF.getUnionSize(0) == N ? "YES" : "NO") << endl;
}

