struct union_find {
	std::vector<long long> parent;
	std::vector<long long> sizes;
	long long num_of_trees;

	//コンストラクタ
	union_find(long long n) {
		for (long long i = 0; i < n; i++) {
			parent.push_back(i);
			sizes.push_back(1);
		}
		num_of_trees = n;
	}

	//頂点nの根
	long long root_of(long long n) {
		if (parent[n] == n) return n;
		return parent[n] = root_of(parent[n]); //パス圧縮
	}

	//頂点nを含む木の頂点数(自身含む)
	long long size_of(long long n) {return sizes[root_of(n)];}

	//頂点a, bが間接的に繋がっているか判定
	bool is_united(long long a, long long b) {return (root_of(a) == root_of(b));}

	//頂点aを含むグラフに頂点bを含むグラフを結合
	void unite(long long a, long long b) {
		if (is_united(a, b)) return;
		num_of_trees--;
		if (size_of(a) < size_of(b)) std::swap(a, b); //マージテク
		sizes[root_of(a)] += size_of(b);
		parent[root_of(b)] = root_of(a);
	}
};

int main() {
	ios::sync_with_stdio(false);
