class UF{
    public:
    vector<lint> data;
    lint sz;
	public:
    UF(lint sz):sz(sz){data.resize(sz,-1);}
    bool unite(lint x,lint y){
        x=root(x);y=root(y);
        if(x==y)return 0;
        if(data[x]>data[y])swap(x,y);
		data[x]+=data[y];
		data[y]=x;
		sz--;
        return 1;
    }
    inline lint root(lint x){return data[x]<0?x:data[x]=root(data[x]);}
    inline bool same(lint x, lint y){return root(x)==root(y);}
    inline lint size(){return sz;}
	inline lint size(lint x){return -data[root(x)];}
};

