struct UnionFind {
  vector<int> par;
  vector<int> sz;
  UnionFind(int n) { init(n); }

  void init(int n) {
    par.resize(n);
    sz.resize(n);
    REP(i, n) {
      par[i] = i;
      sz[i] = 1;
    }
  }

  int find(int x) {
    if (par[x] == x)
      return x;
    else
      return par[x] = find(par[x]);
  }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (sz[x] < sz[y]) {
      par[x] = y;
      sz[y] += sz[x];
    } else {
      par[y] = x;
      sz[x] += sz[y];
    }
  }

  bool same(int x, int y) { return find(x) == find(y); }

  int size(int x) { return sz[find(x)]; }
};

int main() {
  int n, m;
  cin >> n >> m;
  UnionFind uf(200000);
  REP(i, n) {
    int k;
    cin >> k;
    REP(j, k) {
      int l;
      cin >> l;
      uf.unite(i, 100000 + l - 1);
    }
  }
  bool ok = true;
  REP(i, n) {
    if (!uf.same(0, i)) ok = false;
  }
  cout << (ok ? "YES" : "NO") << endl;
  return 0;
}

