int parent[300000], ronk[300000]; //parent, rank (but ronk)

void initset(int n) {
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        ronk[i] = 0;
    }
}

int findset(int x) {
    if(parent[x] == x) return x; //Parent of node is the node itself, this means the node is itself
    parent[x] = findset(parent[x]); //path compression
    return parent[x];
}

bool sameset(int x, int y){
    return findset(x) == findset(y);
}

void mergeset(int x, int y) {
    x = findset(x); // find representatives
    y = findset(y);
    if(ronk[x] > ronk[y]) {
        parent[y] = x;
    } else {
        parent[x] = y;
        if(ronk[x] == ronk[y]) {
            ronk[y]++;
        }
    }
}

