struct union_find {
  vector<long long> parent, sizes;
  void init(long long n) {
    for (long long i = 0; i < n; i++) {
      parent.push_back(i);
      sizes.push_back(1);
    }
  }
  long long root(long long n) {
    if (parent[n] == n) return n;
    return parent[n] = root(parent[n]);
  }
  void unite(long long a, long long b) {
    parent[root(b)] = a;
    sizes[root(a)] += sizes[root(b)];
  }
  bool is_united(long long a, long long b) {return (root(a) == root(b));}
};

int main() {
  long long n, m;
  cin >> n >> m;

  union_find uf;
  uf.init(n);

  vector<vector<long long>> v(m, vector<long long>(0));
  for (long long i = 0; i < n; i++) {
    long long k;
    cin >> k;
    for (long long j = 0; j < k; j++) {
      long long l;
      cin >> l;
      v[l - 1].push_back(i);
    }
  }
  for (long long i = 0; i < m; i++) {
    for (long long j = 1; j < v[i].size(); j++) {
      uf.unite(v[i][0], v[i][j]);
    }
  }

  for (long long i = 1; i < n; i++) {
    if (!uf.is_united(0, i)) {
      cout << "NO" << endl;
      return 0;
    }
  }
  cout << "YES" << endl;
}

