#include <bits/stdc++.h>
using namespace std;

int parent[100000], ranks[100000];

void initset(int n) {
  for (int i = 0; i < n; i++) {
    parent[i] = i;
    ranks[i] = 0;
  }
}

int findset(int x) {
  if (parent[x] == x) return x;
  parent[x] = findset(parent[x]);
  return parent[x];
}

bool sameset(int x, int y) {
  return findset(x) == findset(y);
}

void mergeset(int x, int y) {
  x = findset(x);
  y = findset(y);
  if (ranks[x] > ranks[y]) {
    parent[y] = x;
  }
  else {
    parent[x] = y;
    if (ranks[x] == ranks[y]) {
      ranks[y]++;
    }
