struct DSU {
  VI sz, par;
  DSU(int n) {
    par.resize(n);
    iota(par.begin(), par.end(), 0);
    sz.resize(n, 1);
  }
  int find(int u) {
    if (par[u]  == u) return u;
    return par[u] = find(par[u]);
  }
  void merge(int u, int v) {
    u = find(u), v = find(v);
    if (u != v) {
      par[u] = v;
      sz[v] += sz[u];
    }
  }
  int get(int u) {
    return sz[find(u)];
  }
};

