class UnionFind {
public:
	vector<ll> parent;

	UnionFind(int n) {
		parent = vector<ll>(n, -1);
	}

	int root(int a) {
		if (parent[a] < 0) return a;
		return parent[a] = root(parent[a]);
	}

	int size(int a) {
		return -parent[root(a)];
	}

    bool same(int x, int y){
        return root(x) == root(y);
    }

	bool unite(int a, int b) {
		a = root(a);
		b = root(b);
		if (a == b) {
			return false;
		}

		if (size(a) < size(b)) swap(a, b);

		parent[a] += parent[b];
		parent[b] = a;

		return true;
	}
};

int main(){

    ll n, m;
    cin >> n >> m;

    UnionFind uf(n+m);
    rep(i, n){
        int k; cin >> k;
        rep(j, k){
            int l; cin >> l;
            uf.unite(i, n-1+l);
        }
    }

    rep(i, n-1){
        if(!uf.same(i, i+1)){
            NO();
            return 0;
        }
    }
    YES();

    return 0;
}

