    vec k(n);
    vec l[100010];
    rep(i, n) {
        cin >> k[i];
        l[i].resize(k[i]);
        rep(j, k[i]) {
            cin >> l[i][j];
            --l[i][j];
        }
    }

    UnionFind uf(n);
    vec lv[100010];

    rep(i, n) {
        rep(j, k[i]) {
            for (auto&& k : lv[l[i][j]]) uf.unite(i, k);

            lv[l[i][j]].push_back(i);
        }
    }

    if (uf.size(0) == n) cout << "YES" << endl;
    else cout << "NO" << endl;
    return 0;
}

