        last_L = L - 1;
      }
      else {
        unite(last_L, L - 1);
        last_L = L - 1;
      }
    }
  }
  ll par_ind = -1;
  for (ll i = 0; i < M; ++i) {
    if (!used.at(i)) {
      continue;
    }
    if (par_ind == -1) {
      par_ind = par.at(i);
    }
    else {
      if (par_ind != par.at(i)) {
        cout << "NO" << endl;
        return 0;
      }
    }
  }
  cout << "YES" << endl;
}

