struct UFtree {
    i64 n;
    VL par;
    VL rank;
    VL group_size;
    UFtree(i64 num_of_elm) : n(num_of_elm), par(num_of_elm, 0), rank(num_of_elm, 0), group_size(num_of_elm, 1) {
        for (i64 i = 0; i < num_of_elm; ++i) par[i] = i;
    }

    i64 find_root(i64 x) {
        i64 parent = par[x];
        if (parent == x) {
            return x;
        } else {
            i64 root = find_root(parent);
            // 経路圧縮
            par[x] = root;
            return root;
        }
    }

    bool is_same(i64 x, i64 y) {
        return (find_root(x) == find_root(y));
    }

    bool unite(i64 x, i64 y) {
        i64 shallow = find_root(x);
        i64 deep = find_root(y);
        if (rank[shallow] > rank[deep]) {
            swap(shallow, deep);
        }
        if (shallow == deep) {
            return false;
        } else {
            par[shallow] = deep;
            group_size[deep] += group_size[shallow];
            if (rank[shallow] == rank[deep]) rank[deep]++;
            return true;
        }
    }

    i64 akin_num(i64 x) {
        i64 root = find_root(x);
        return group_size[root];
    }
};



