			tree.unite(L[i][j],L[i][j+1]);
		}
	}

	int root = tree.root(*st.begin());
	for(auto x:st){
		if(!tree.same(root,x)){
			cout << "NO" << endl;
			return 0;
		}
	}
	cout << "YES" << endl;
}

