struct UnionFind {
    vector<int> tree;
    explicit UnionFind(size_t n) : tree(n + 5, -1) {}

    int size(int i) { return (-tree[root(i)]); }

    int root(int x) { return (tree[x] < 0) ? x : tree[x] = root(tree[x]); }

    bool same(int x, int y) { return root(x) == root(y); }

    bool unite(int x, int y) {
        return (x = root(x)) == (y = root(y)) ? false : (tree[x] += tree[y], tree[y] = x, true);
    }
};
