//warshallFloyd
int V = 1000;
static const int MAX_V = 1000;
int d[MAX_V][MAX_V];

void warshallFloyd() {
	rep(k, V) {
		rep(i, V) {
			rep(j, V) {
				if (d[i][k] == INF || d[k][j] == INF) continue;
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
			}
		}
	}
}

