struct UnionFind{
	vi rank,par;
	void Init(int n){
		rank.assign(n,0);
		par.assign(n,-1);
	}
	int Find(int i){
		return par[i]==-1?i:(par[i]=Find(par[i]));
	}
	bool Same(int a,int b){
		return Find(a)==Find(b);
	}
	bool Unite(int a,int b){
		a=Find(a);
		b=Find(b);
		if(a==b)
			return false;
		if(rank[a]<rank[b])
			swap(a,b);
		par[b]=a;
		if(rank[a]==rank[b])
			rank[a]++;
		return true;
	}
} uf;

int main(){
	int n=read(),m=read();
	uf.Init(n+m);
	REP(i,n){
		int k=read();
		REP(_,k){
			int l=read();
			uf.Unite(i,n+l-1);
		}
	}
	bool same=true;
	FOR(i,1,n)
		if(!uf.Same(0,i))
			same=false;
	if(same)
		cout<<"YES"<<endl;
	else
		cout<<"NO"<<endl;
}

