struct UnionFind {
    vector<int> data;
    UnionFind(int size) : data(size, -1) { }
    bool unionSet(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};

int main(void)
{
    int N, M;
    cin >> N >> M;

    int K, L;
    vector<int> *lang = new vector<int>[M];
    UnionFind u(N);

    for (int i = 0; i < N; i++) {
        cin >> K;

        for (int j = 0; j < K; j++) {
            cin >> L;
            lang[L - 1].push_back(i);

            for (int k = 0; k < lang[L - 1].size() - 1; k++)
                u.unionSet(lang[L - 1][k], i);
        }
    }

    delete[] lang;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (!u.findSet(i, j)) {
                cout << "NO" << endl;
                return 0;
            }
        }
    }

    cout << "YES" << endl;
    return 0;
}

