struct Node{
    bool people;
    vector<Node*> dests;
    Node(bool people = false): people(people){}
    void find(set<Node*>& visited){
        if(visited.count(this)){ return; }
        if(people){ cnt++; }
        visited.insert(this);
        for(Node* d : dests){
            d -> find(visited);
        }
    }
};

int main(){
    int n, m;
    cin >> n >> m;
    vector<Node> ns(n, {true}), ls(m);
    for(int i=0;i<n;i++){
