            l--;
            ns[i].dests.push_back(&ls[l]);
            ls[l].dests.push_back(&ns[i]);
        }
    }
    set<Node*> visited;
    ns[0].find(visited);
    cout << (cnt == n ? "YES" : "NO") << endl;
    return 0;
}

