struct DisjointSet {
    vector<int64_t> par; //根.連結成分の根にはその成分の要素数を符号反転して保存する．

    DisjointSet(int64_t n) : par(n, -1) {} //.0-indexed 
    void init(int64_t n) {par.assign(n, -1);}// 初期化

    int root(int64_t x) {
        if (par[x] < 0) return x; //根が負なら自身が根．
        else return par[x] = root(par[x]); //径路圧縮
    }

    // 連結判定
    bool issame(int64_t x, int64_t y) { return root(x) == root(y); }

    bool unite(int64_t x, int64_t y) { // 結合が行われればtrue.行われなければfalse.
        x = root(x); y = root(y); // 径路圧縮
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); 
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int64_t size(int64_t x){ return -par[root(x)]; }
};

