typedef long long int ll;

int parent[200005], ranks[200005];

void initset(int n)
{
	for (int i = 0; i <= n; i++)
	{
		parent[i] = i;
		ranks[i] = 0;
	}
}
// Return representative index
int findset(int x)
{
	// Value of representative index is itself
	if (parent[x] == x)
		return x;
	parent[x] = findset(parent[x]); // Path compression; set value/arrow to representative index
	return parent[x];
}

bool sameset(int x, int y)
{ // Same set would have same rep index
	return findset(x) == findset(y);
}

// Input: 2 nodes which may not be representatives
void mergeset(int x, int y)
{
	x = findset(x);
	y = findset(y);
	if (ranks[x] > ranks[y])
	{
		parent[y] = x;
	}
	else if (ranks[y] > ranks[x])
	{
		parent[x] = y;
	}
	else
	{
		parent[x] = y;
		ranks[y]++;
	}
}

int N, M, K, L;
int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	cin >> N >> M;
	initset(N + M + 5); // 5 is buffer
	for (int i = 0; i < N; i++)
	{
		cin >> K;
		for (int j = 0; j < K; j++)
		{
			cin >> L;
			// 1-indexing for people; N+L is for language number, "N"-indexing
			mergeset(i + 1, N + L);
		}
	}

	for (int i = 1; i <= N; i++)
	{
		if (!sameset(i, 1))
		{
			cout << "NO\n";
