class Xorshift {
 public:
  Xorshift() {
    seed0_ = static_cast<uint64_t>(
        std::chrono::steady_clock::now().time_since_epoch().count());
    seed1_ = static_cast<uint64_t>(
        std::chrono::steady_clock::now().time_since_epoch().count());
  }
  using result_type = uint64_t;
  static constexpr uint64_t min() {
    return std::numeric_limits<result_type>::min();
  }
  static constexpr uint64_t max() {
    return std::numeric_limits<result_type>::max();
  }
  uint64_t operator()() { return GetNext(); }

 private:
  uint64_t result_;
  uint64_t seed0_;
  uint64_t seed1_;
  uint64_t GetNext() {
    uint64_t s1 = seed0_;
    uint64_t s0 = seed1_;
    result_ = s0 + s1;
    seed0_ = s0;
    s1 ^= s1 << 23;
    seed1_ = s1 ^ s0 ^ (s1 >> 18) ^ (s0 >> 5);
    return result_;
  }
};

class UnionFind {
 public:
  UnionFind(int n) : n_(n) { Initialize(); }
  int GetRoot(int x);
  bool IsSame(int x, int y);
  void Unite(int x, int y);
  int GetSize(int x);

 private:
  const int n_;
  std::vector<int> parent_;
  void Initialize();
};

inline void UnionFind::Initialize() { parent_.assign(n_, -1); }

inline int UnionFind::GetRoot(int x) {
  if (parent_[x] < 0)
    return x;
  else
    return parent_[x] = GetRoot(parent_[x]);
}

inline bool UnionFind::IsSame(int x, int y) { return GetRoot(x) == GetRoot(y); }

inline void UnionFind::Unite(int x, int y) {
  x = GetRoot(x);
  y = GetRoot(y);
  if (x == y) return;
  if (parent_[x] > parent_[y]) std::swap(x, y);
  parent_[x] += parent_[y];
  parent_[y] = x;
  return;
}

inline int UnionFind::GetSize(int x) { return -parent_[GetRoot(x)]; }

class person {
 public:
  vector<int> language;
  int original_number;
};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n, m; cin >> n >> m;
  vector<person> l(n);
  for (int i = 0; i < n; ++i) {
    int k; cin >> k;
    vector<int> t(k);
    for (int j = 0; j < k; ++j) {
      cin >> t[j];
    }
    sort(t.begin(), t.end());
    l[i] = (person){t, i};
  }

  UnionFind uf(n);
  Xorshift xor128;

  for (int loop = 0; loop < 100; ++loop) {
    shuffle(l.begin(), l.end(), xor128);
    for (int i = 0; i < n - 1; ++i) {
      for (int j = 0; j < l[i].language.size(); ++j) {
        if (uf.IsSame(i, i + 1)) break;
        if (binary_search(l[i + 1].language.begin(), l[i + 1].language.end(), l[i].language[j])) {
          uf.Unite(l[i].original_number, l[i + 1].original_number);
          break;
        }
      }
    }
  }

  if (uf.GetSize(0) == n) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }

  return 0;
}

