int rootVal(int a, vector<int> &v){
	if(v[a] < 0) return v[a] * -1;
	return v[a] = rootVal(v[a], v);
}
int root(int a, vector<int> &v){
	if(v[a] < 0) return a;
	return v[a] = root(v[a], v);
}
bool connect(int a, int b, vector<int> &v, vector<int> &c1, vector<int> &c2, vector<int> &lanlon){
	a = root(a, v);
	b = root(b, v);
	if(a == b) return false;

	bool flag = false;
	for(int i = 0; i < lanlon[a]; i++){
		for(int j = 0; j < lanlon[b]; j++){
			if(c1[i] == c2[j]){
				flag = true;
				break;
			}
		}
		if(flag) break;
	}

	if(!flag) return false;

	if(v[a] > v[b]){
		v[a] ^= v[b];
		v[b] ^= v[a];
		v[a] ^= v[b];
	}
	v[a] += v[b];
	v[b] = a;
	return true;
}

