const int MAX_N = 1e5;
class UnionFind {
private:
    int rank[MAX_N];

public:
    int par[MAX_N];

    void init(int n)
    {
        for (int i=0; i<n; i++) {
            par[i]=i;
            rank[i]=0;
        }
    }

    // 木の根を求める
    int find(int x)
    {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    // xとyの属する集合を併合する
    void merge(int x, int y)
    {
        x = find(x);
        y = find(y);
        if (x == y) return;

        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
    }

    // xとyが同じ集合に属するか判定する
    bool same(int x, int y)
    {
        return find(x) == find(y);
    }
};

const int MAX_M = 1e5;
set<int> can[MAX_M];

int main()
{
    ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;
    rep(i, N) {
