        }
    }

    UnionFind UF;
    UF.init(N);

    rep(i, M) {
        if (can[i].size() == 0) continue;
        for (auto u : can[i]) {
            UF.merge(i, u);
        }
    }

    bool ok = true;
    rep(i, N) {
        if (!UF.same(i, 0)) ok = false;
    }
    cout << (ok ? "YES" : "NO") << endl;
}

