void RegisterNewLanguage(int newLanguage, vector<bool>& visitedLanguages,
                         vector<bool>& visitedSpeakers) {
  visitedLanguages[newLanguage] = true;

  for (int speaker : languageSpeakers[newLanguage]) {
    if (visitedSpeakers[speaker]) continue;
    visitedSpeakers[speaker] = true;

    for (int language : speakLanguages[speaker]) {
      if (visitedLanguages[language]) continue;
      RegisterNewLanguage(language, visitedLanguages, visitedSpeakers);
    }
  }
}

