    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;

        if (par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;

        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N,M;cin>>N>>M;
    UnionFind uf(N);

    vector<vector<int>> G(M);

    rep(i, N) {
        int n; cin >> n;
        rep(j, n) {
            int a; cin >> a; --a;
            G[a].push_back(i);
        }
    }

    rep(i, M) {
        if(G[i].size() < 2) continue;

        int n = G[i].size()-1;
        int one = G[i][0];
        rep1(j, n) {
            uf.merge(one, G[i][j]);
        }
    }

    int root = uf.root(0);
    rep1(i, N - 1) {
        if(uf.root(i) != root) {
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;
}

