ll func(vvl &G, vector<bool> &used, ll M, ll s) {
  ll c = 0;
  if (s == M)
    c++;
  used[s] = true;
  AUTO(g, G[s]) {
    if (!used[g]) {
      used[g] = true;
      c += func(G, used, M, g);
      if (g >= M)
        c++;
    }
  }
  return c;
}

