struct UFTree {
private:
	vector<int> mNode;
	vector<int> mRank;

public:
	UFTree(int n) : mNode(n), mRank(n)
	{
		for (int i = 0; i < n; i++) {
			mNode[i] = i;
		}
	}

	int find(int x)
	{
		if (mNode[x] == x) {
			return x;
		}
		else {
			mNode[x] = find(mNode[x]);
			return mNode[x];
		}
	}

	void unite(int x, int y)
	{
		int idxX = find(x);
		int idxY = find(y);

		if (idxX == idxY) {
			return;
		}

		if (mRank[idxX] > mRank[idxY]) {
			mNode[idxY] = idxX;
		}
		else {
			mNode[idxX] = idxY;
			if (mRank[idxX] == mRank[idxY]) {
				mRank[idxY]++;
			}
		}
	}

	bool isSameSet(int x, int y)
	{
		return find(x) == find(y);
	}
};

