      int L;
      cin >> L;
      uf.unite(--L, M + i);
    }
  }
  int root = uf.find(M);
  for(int i = 0; i < N; i++) {
    if(root != uf.find(M + i)) {
      cout << "NO" << endl;
      return (0);
    }
  }
  cout << "YES" << endl;
}

