using namespace std;

struct UnionFind {
    vector<int> data;
    UnionFind(int size) : data(size, -1) { }
    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};

int main()
{
    int N, M;
    cin >> N >> M;
    vector<vector<int>> L(N);
    for (auto& v : L) {
        int K;
        cin >> K;
        v.resize(K);
        for (auto& x : v) {
            cin >> x;
            --x;
        }
    }

    UnionFind u(N);
    vector<vector<int>> v(M);
    for (int i = 0; i < N; ++i) {
        for (auto x : L[i]) {
            if (v[x].empty()) {
                v[x].push_back(i);
            }
            else {
                u.unite(v[x][0], i);
            }
        }
    }
    if (u.size(0) == N) {
        cout << "YES" << endl;
    }
    else {
        cout << "NO" << endl;
    }
}

