using namespace std;
int par[100000];
int rank_[100000];

int find(int x){
    if(par[x]==x){
        return x;
    }else{
        return par[x]=find(par[x]);
    }
}

void unite(int x, int y){
    x=find(x);
    y=find(y);
    if(x==y)return;
    if(rank_[x]<rank_[y]){
        par[x]=y;
    }else{
        par[y]=x;
        if(rank_[x]==rank_[y]) rank_[x]++;
    }
}

bool exist[100000];

int main(){
    int N,M;
    cin>>N>>M;
    for(int i=0;i<M;i++){
        par[i]=i;
        rank_[i]=0;
    }
    for(int i=0;i<N;i++){
        int Ki;
        cin>>Ki;
        vector<int> L(Ki);
        for(int j=0;j<Ki;j++){
            cin>>L[j];
            L[j]--;
            exist[L[j]]=true;
        }
        for(int j=1;j<Ki;j++){
            unite(L[0],L[j]);
        }
    }
    int p;
    for(int i=0;i<M;i++){
        if(exist[i]){
            p=find(i);
            break;
        }
    }
