struct UnionFind {
	vector<int> par;
	vector<int> rank;
	vector<int> size;

	UnionFind(int N) : par(N), rank(N), size(N){
		rep(i,N){
			par[i] = i;
			rank[i] = 0;
			size[i] = 1;
		}
	}

	int root(int x) {
		if (par[x] == x) return x;
		par[x] = root(par[x]);
		return par[x];
	}

	void unite(int x, int y){
		int rx = root(x);
		int ry = root(y);
		if(rx == ry) return;
		if(rank[rx] < rank[ry]){
			par[rx] = ry;
			size[ry] += size[rx];
		}else{
			par[ry] = rx;
			size[rx] += size[ry];
			if(rank[rx] == rank[ry]) rank[rx]++;
		}
	}

	bool same(int x, int y){
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}
};

int main(){
	int n,m;
	cin >> n >> m;
	UnionFind uf(n+m);
	rep(i,n){
		int k;
		cin >> k;
		rep(j,k){
			int l;
			cin >> l;
			l--;
			uf.unite(i, n+l);
		}
	}

	bool ok = true;
	int a = uf.root(0);

	rep(i,n){
		if(a != uf.root(i)) ok = false;
	}
	if(ok){
		cout << "YES" << endl;
	}else{
		cout << "NO" << endl;
	}

    return 0;
}

