struct Node {
    vector<int> adjacents = vector<int>();
    bool flag = false;
};
int main() {
    int n, m;
    cin >> n >> m;
    auto nodes = vector<Node>(n + m);
    rep(i, n) {
        int k;
        cin >> k;
        rep(j, k) {
            int l;
            cin >> l;
            l += n - 1;
            nodes[i].adjacents.PB(l);
            nodes[l].adjacents.PB(i);
        }
    }
    function<void(int, int)> reach = [&](int index, int prev) {
        auto &node = nodes[index];
        node.flag = true; // 訪問済みフラグを立てる
        for (auto nextIndex : node.adjacents) {
            if (nextIndex == prev)
                continue; // 一つ前のノードに戻らない
            if (nodes[nextIndex].flag)
                continue; // 訪問済みノードはスキップ
            reach(nextIndex, index); // 隣接ノードに訪問済みフラグを立ててゆく
        }
    };
    reach(0, -1); // ノード0を起点にして隣接全頂点をDFSで訪問
    rep(i, n) {
        if (nodes[i].flag == false) {
            PUTS("NO");
            return 0;
        }
    }
    PUTS("YES");
}

