struct UnionFind
{
	vector<int> p;
	UnionFind(int n) :p(n) {
		for (int i = 0; i < n; i++) {
			p[i] = i;
		}
	}

	int root(int x) {
		int px = p[x];
		if (px == x) {
			return x;
		}

		p[x] = root(px);
		return p[x];
	}

	void unite(int x, int y) {
		int rx = root(x);
		int ry = root(y);
		if (rx == ry) {
			return;
		}

		p[rx] = ry;
	}
};

int main() {
