        rep(j,lang[i].size()){
            if(j!=lang[i].size()-1){
                unite(lang[i][j],lang[i][j+1]);
            }
        }
    }
    bool f=1;
    REP(i,1,n){
        f&=same(i,i+1);
    }
    cout<<(f?"YES":"NO")<<endl;
}

