auto solve(ll n, const V<pair<PAIR, ll>>& v) {
  VL ans(n + 1, 1e18);
  auto bits = [&](ll sz, const VL& p) {
    REP(i, (1 << sz)) {
      VL x, y;
      x.reserve(sz);
      y.reserve(sz);
      REP(j, sz) {
	if ((i >> j) & 1) {
	  x.emplace_back(v[p[j]].first.first);
	} else {
	  y.emplace_back(v[p[j]].first.second);
	}
      }
      ll cst = 0;
      for (cauto[xy, tt] : v) {
	cauto[xx, yy] = xy;
	ll tmp = std::min(std::abs(xx), std::abs(yy));
	REPC(t, x) { chmin(tmp, std::abs(t - xx)); }
	REPC(t, y) { chmin(tmp, std::abs(t - yy)); }
	cst += tmp * tt;
      }
      if (cst == 600) {
	auto k = std::bitset<3>(i);
      }
      chmin(ans[sz], cst);
    }
  };

  FOR(sz, 1, n + 1) {
    VL p(sz);
    auto add = [&]() {
      ll i = sz - 1;
      ++p[i];
      while (p[i] + (sz - i - 1) == n) {
	--i;
	if (i == -1) {
	  return false;
	}
	++p[i];
      }
      FOR(k, i + 1, sz) { p[k] = p[k - 1] + 1; }
      return p[sz - 1] < n;
    };

    std::iota(ALL(p), 0);
    do {
      bits(sz, p);
    } while (add());
  }

  ans[0] = 0;
  for (cauto[xy, tt] : v) {
    cauto[x, y] = xy;
    ans[0] += std::min(std::abs(x), std::abs(y)) * tt;
  }
  return ans;
}

class UnionFind {
  std::vector<ll> m_root;
  std::vector<ll> m_depth;
  std::vector<ll> m_size;

 public:
  UnionFind(ll size_) : m_root(size_), m_depth(size_, 0), m_size(size_, 1) {
    std::iota(m_root.begin(), m_root.end(), 0);
  }
  void unite(ll x, ll y) {
    x = root(x);
    y = root(y);
    if (x == y) return;
    ll t = size(x) + size(y);
    m_size[x] = m_size[y] = t;
    if (m_depth[x] < m_depth[y])
      m_root[x] = y;
    else
      m_root[y] = x;
    if (m_depth[x] == m_depth[y]) ++m_depth[x];
  }
  bool isSame(ll x, ll y) { return root(x) == root(y); }
  ll root(ll x) {
    if (m_root[x] == x) return x;
    return m_root[x] = root(m_root[x]);
  }
  ll size(ll x) {
    if (m_root[x] == x) return m_size[x];
    return size(m_root[x] = root(m_root[x]));
  }
};

signed main() {
  ll n, m;
  cin >> n >> m;
  auto tree = UnionFind(m + n);
  VL check(n);
  REP(i, n) {
    ll k;
    cin >> k;
    REP(_, k) {
      ll l;
      cin >> l;
      --l;
      tree.unite(i, n + l);
      check[i] = l;
    }
  }
  FOR(i, 1, n) if (!tree.isSame(0, i)) {
    cout << "NO" << endl;
    return 0;
  }
  cout << "YES" << endl;
}

