#define	MOD 1000000007

int	main() {
	int N, M;
	cin >>N >>M;
	vector<vector<int>> L(M);
	for (int i=0; i<N; i++) {
		int K;
		cin >>K;
		for (int j=0; j<K; j++) {
			int LL;
			cin >>LL;
			LL--;// From 0 to M-1
			// Member: i speaks Language LL
			L.at(LL).push_back(i);
		}
	}
	// Struct for each node
	struct Node {
		vector<int> to_node;
		bool fix;
	};
	vector<Node> node(N);
	// Initialize
	for (int i=0; i<node.size(); i++)
		node.at(i).fix=false;
	// Data for each node
	for (int i=0; i<M; i++) {
		if (2>L.at(i).size())
			continue;
		for (int j=0; j<L.at(i).size()-1; j++) {
			for (int k=j+1; k<L.at(i).size(); k++) {
				int F=L.at(i).at(j);
				int T=L.at(i).at(k);
				if (F==T)
					continue;
				node.at(F).to_node.push_back(T);
				node.at(T).to_node.push_back(F);
			}
		}
	}
	// Start
	// Start Node == Cost=0
	int StartNode=0;
	vector<int> q;
	int ixq=0;
	q.push_back(StartNode);
	// For all reachable node from the start node (Unreachabel node not included)
	while (ixq<q.size()) {
		// Pickup the Node with minimum cost
		int ii=q.at(ixq);
		ixq++;
		// If fixed, skip
		if(node.at(ii).fix)
			continue;
		// Change it to fixed and search for near-by nodes
		node.at(ii).fix=true;
		for (int i=0; i<node.at(ii).to_node.size(); i++) {
			int o_node=node.at(ii).to_node.at(i);
			// Push into queue
			if (!node.at(o_node).fix)
				q.push_back(o_node);
		}
	}
	for (int i=0; i<N; i++)
		if (!node.at(i).fix) {
			cout <<"NO" <<endl;
			return 0;
		}
	cout <<"YES" <<endl;
	return 0;
}

