int parent[200005], ranks[200005];

void initset(int n)
{
    for (int i = 0; i < n; i++)
    {
        parent[i] = i;
        ranks[i] = 0;
    }
}

int findSet(int x)
{
    if (parent[x] == x)
        return x;

    parent[x] = findSet(parent[x]);

    return parent[x];
}

bool sameSet(int x, int y)
{
    return findSet(x) == findSet(y);
}

void mergeSet(int x, int y)
{
    x = findSet(x);
    y = findSet(y);
    if (ranks[x] > ranks[y])
    {
        parent[y] = x;
    }
    else
    {
        parent[x] = y;
        if (ranks[x] == ranks[y])
        {
            ranks[y]++;
        }
    }
}

