struct unionfind{
    vector<int> rank,parent,size;
    int independent_tree;
    int N;

    unionfind(int n){
        N=n;
        for(int i=0;i<n;i++){
            rank.push_back(1);
            parent.push_back(i);
            size.push_back(1);
            independent_tree=N;
        }
    }
    int getroot(int x){
        if(parent[x]==x)
            return x;
        return parent[x]=getroot(parent[x]);
    }
    bool issame(int a,int b){
        return getroot(a)==getroot(b);
    }
    void unite(int a,int b){
        a=getroot(a);
        b=getroot(b);
        if(a==b)
            return;
        else if(rank[a]>rank[b]){
            parent[b]=a;
            size[a]+=size[b];
        }
        else if(rank[a]==rank[b]){
            parent[b]=a;
            rank[a]++;
            size[a]+=size[b];
        }
        else{
            parent[a]=b;
            size[b]+=size[a];
        }
    }
};

