template <typename T>
class UnionFind
{
private:
	vector<T> par;
	vector<T> rank;

public:
	UnionFind(T N) : par(N), rank(N)
	{
		for (T i = 0; i < N; ++i) par[i] = i;
	}

	T root(T x)
	{
		return par[x] == x ? x : par[x] = root(par[x]);
	}

	bool same(T x, T y)
	{
		return root(x) == root(y);
	}

	void unite(T x, T y)
	{
		x = root(x);
		y = root(y);
		if (x == y) return;

		if (rank[x] < rank[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (rank[x] == rank[y]) ++rank[x];
		}
	}
};





int main()
