			if (reached[ooo] == false) {
				size++;
				if (size == lim_size) {
					while(!queue.empty()) {
						queue.pop();
					}
					break;
				}
				queue.push(ooo);
				reached[ooo] = true;
			}
		}
	}

	if (size != lim_size) {
		cout << "NO" << endl;
		return 0;
	}
	cout << "YES" << endl;
	return 0;
}

