            L--;
            l[L].push_back(i);
        }
    }
    for(int i=0; i<l.size(); ++i) {
        for(int j=1; j<l[i].size(); ++j) {
            uf.unite(l[i][j], l[i][j-1]);
        }
    }
    for(int i=0; i<N-1; ++i) {
        if(!uf.same(i, i+1)) {
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;
}

