    int l = vv;
    while (v[l].sc == v[vv].sc)
    {
        l--;
    }
    l++;
    int pos = l;

    for (int i = 0; i < g[vv].size(); i++)
    {
        int to = g[vv][i];

        if (!used[to])
           dfs(to);
    }
    if (v[vv].sc != 1){

        for (int j = pos; j < v.size(); j++)
        {
            if (v[j].sc != v[vv].sc)
                return;
            if (!used[j] && g[j].size() > 0)
                dfs(j);
        }

    }

}
