class UnionFind {
public:
	vector<int>rank, parent;
	//������
	UnionFind(int size) {
		rank.resize(size, 0);
		parent.resize(size, 0);
		REP(i, size)parent[i] = i;
	}
	//�؂̍������߂�
	int find(int x) {
		if(parent[x] == x)return x;
		else return parent[x] = find(parent[x]);
	}
	//x��y�̑�����W���𕹍�
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if(x == y)return;
		if(rank[x] < rank[y])
			parent[x] = y;
		else {
			parent[y] = x;
			if(rank[x] == rank[y])rank[x]++;
		}
	}
	//x��y�������W���ɑ����邩�ۂ�
	bool same(int x, int y) {
		return (find(x) == find(y));
	}
	//parent�̓��e���o��
	void debug() {
		for(auto num : parent) {
			cout << num << " ";
		}
		cout << "more:" << endl;
		REP(i, parent.size()) {
			cout << find(i) << " ";

		}
		cout << endl << "more:" << endl;
		for(auto num : parent) {
			cout << num << " ";
		}
		cout << endl;
	}
};


