struct UnionFind {
    //親の番号を格納する。親だった場合は-(その集合のサイズ)
    vll parent;
    vll mini;
    vll maxi;
    ll N;

    //作るときはParentの値を全て-1にする
    //こうすると全てバラバラになる
    UnionFind(ll n)
    {
        this->N = n;
        this->parent = vll(n, -1);
        this->mini = vll(n);
        this->maxi = vll(n);
        for1 (i, n) {
            this->mini[i] = i;
            this->maxi[i] = i;
        }
    }

    // Aがどのグループに属しているか調べる
    ll root(ll A)
    {
        if (this->parent[A] < 0) return A;
        return this->parent[A] = this->root(this->parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    ll size(ll A)
    {
        return -this->parent[this->root(A)];  //親をとってきたい
    }

    // AとBをくっ付ける
    bool connect(ll A, ll B)
    {
        // AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = this->root(A);
        B = this->root(B);
        if (A == B) {
            //すでにくっついてるからくっ付けない
            return false;
        }

        //大きい方(A)に小さいほう(B)をくっ付けたい
        //大小が逆だったらひっくり返しちゃう。
        if (this->size(A) < this->size(B)) {
            swap(A, B);
        }

        // Aのサイズを更新する
        this->parent[A] += this->parent[B];
        // Bの親をAに変更する
        this->parent[B] = A;
        chmax(this->maxi[A], this->maxi[B]);
        chmin(this->mini[A], this->mini[B]);

        return true;
    }
};
//---------------------------------------------------------
void solve()
{
    ll N, M;
    in(N, M);
    UnionFind uni(N + M);
    for1 (i, N) {
        ll K;
        in(K);
        for1 (j, K) {
            ll L;
            in(L);
            --L;
            uni.connect(i, N + L);
        }
    }
    bool ans = true;
    for1 (i, N) {
        if (uni.root(0) != uni.root(i)) {
            ans = false;
        }
    }
    if (ans) {
        YES();
    }
    else {
        NO();
    }
}
