		K[i] = k;
		rep(j,k){
			int lan;
			cin >> lan;
			if(j==0){
				L[i] = lan;
			} else {
				uf.unite(L[i],lan);
			} 
		}
	}
	rep(i,n){
		if(uf.same(L[0],L[i])){
		} else {
			puts("NO");
			return 0;
		}
	}
	puts("YES");
}

