int main(){
    int n,m; cin >> n >> m;
    vector<vector<int> > lag(m);
    vector<vector<int> > abts(n);
    rep(i,n){
        int k; cin >> k;
        rep(j,k){
            int l; cin>> l;
            l--;
            lag[l].push_back(i);
            abts[i].push_back(l);
        }
    }

    vector<int> check(n,0);
    vector<int> lcheck(m,0);
    queue<int> q;
    q.push(0);
    check[0]++;

    while(!q.empty()){
        int now=q.front();
        q.pop();
        for(int x : abts[now]){
