            ans = true;
        }

//        cout << tree[i].sum << endl;
    }

    if (ans) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
}

void unite(ll a, ll b) {
    a = root(a);
    b = root(b);

    if (a != b) {
        if (tree[a].man && tree[b].man) {
            tree[a].sum = tree[a].sum + tree[b].sum;

            tree[b].sum = a;
        } else if (tree[a].man && !tree[b].man) {
            tree[b].sum = a;
        } else {
            tree[a].sum = b;
        }
    }

    return;
}

ll root(ll a) {
    if (tree[a].sum < 0) {
        return a;
    } else {
        tree[a].sum = root(tree[a].sum);
    }
}

