//find  どのグループか調べる
struct UnionFind {
    vector<LL> parent;

    UnionFind(LL n) : parent(n, -1) { }
    void init(LL n) { parent.assign(n, -1); }

    //xの属している木の根っこを返す
    LL root(LL x) {
        if (parent[x] < 0) return x;
        else return parent[x] = root(parent[x]);//経路圧縮
    }

    LL size(LL x) {return -parent[root(x)];}//xの属する木の要素数を求める
    bool is_same_tree(LL x,LL y) {return root(x)==root(y);}

    bool merge(LL x,LL y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (parent[x] > parent[y]) swap(x, y);//xの親の方がyの親より小さくなるようにする
        parent[x] += parent[y];//経路の長さを加算
        parent[y] = x;//yの親をxとする
        return true;
    }
};

LL N,M;
vector<LL> K;
vector<vector<LL>> L;

string ans = "YES";

void solve(){
	UnionFind uf(M);
	vector<int> used(M,0);//言語iが既に登場したかどうかをused[i]とする
	int lang_num = 0;//既に登場した言語の総数
	for(int i=0;i<N;i++){
		for(int j=0;j<K[i];j++){
			if(!used[L[i][j]]){
				used[L[i][j]] = 1;
				lang_num++;
			}
		}
	}

	for(int i=0;i<N;i++){
		for(int j=1;j<K[i];j++){
			uf.merge(L[i][j],L[i][j-1]);
		}
	}
	for(int i=0;i<M;i++){
		if(used[i]){
			if(uf.size(i)<lang_num) ans = "NO";
		}
	}
}

int main(){
    cin >> N >> M;
    K = vector<LL>(N);
    L = vector<vector<LL>>(N);
    for(int i=0;i<N;i++){
    	cin >> K[i];
    	for(int j=0;j<K[i];j++){
    		LL a;cin>>a;a--;
    		L[i].push_back(a);
    	}
    }

    solve();

	cout << ans << endl;
    return 0;
}

