struct UnionFind{
    vector<ll> par;
    vector<ll> siz;
    UnionFind(ll N): par(N),siz(N,1LL){
        rep(i,N)par[i]=i;
    }
    void init(ll N){
        par.resize(N);
        siz.assign(N,1LL);
        rep(i,N)par[i]=i;
    }

    ll root(ll x){
        if(par[x]==x)return x;
        return par[x]=root(par[x]);
    }

    ll size(ll x){
        return siz[root(x)];
    }
    bool unite(ll x,ll y){
        ll rx = root(x);
        ll ry = root(y);
        if(rx==ry) return false;
        if(siz[rx]<siz[ry])swap(rx,ry);
        siz[rx]+=siz[ry];
        par[ry] = rx;
        return true;
    }
    bool same(ll x,ll y){
        ll rx = root(x);
        ll ry = root(y);
        return rx==ry;
    }
};


