using namespace std;
struct UnionFind {
	vector<int> par;

	UnionFind(int N) : par(N) {
		for(int i = 0; i < N; i++) par[i] = i;
	}

	int root(int x) {
		if(par[x] == x) return x;
			//ここで併合処理も行なっている
		return par[x] = root(par[x]);
	}

	void unite(int x, int y) {
		int rx = root(x);
		int ry = root(y);
		if(rx == ry) return;
		par[rx] = ry;
	}

	bool same(int x, int y) {
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}

};


int main() {
	int N;
	cin >> N;
	UnionFind a(N);
	int M;
	cin >> M;
	vector<vector<int> > L(N);

	for(int i = 0; i < N; i++) {
		int ki;
		cin >> ki;
		L[i] = vector<int>(ki);
		for(int j = 0; j < ki; j++) {
			cin >> L[i][j];
		}
		sort(L[i].begin(), L[i].end());
	}

	for(int i = 0; i < N; i++) {
		int im = L[i].size();
		for(int j = i + 1; j < N; j++) {
			if(a.same(i, j) == true) continue;
			int ii = 0;
			int ji = 0;
			int jm = L[j].size();
			while(ii < im && ji < jm) {
				if(L[i][ii] == L[j][ji]) {
					a.unite(i, j);
					break;
				} else if(L[i][ii] < L[j][ji]) {
					ii++;
				} else {
					ji++;
				}
			}
		}
	}

	for(int i = 0; i < N; i++) {
		for(int j = i + 1; j < N; j++) {
			if(a.same(i, j) == false) {
				cout << "NO" << endl;
				return 0;
			}
		}
	}
	cout << "YES" << endl;
}

