vector<bool> visited;
vector<vi> langs;
vector<vi> speaks;
void dfs(int pos) {
	visited[pos] = true;

	for (int L : speaks[pos]) {
		for (int i = langs[L].size()-1; i; --i) {
			if (!visited[langs[L][i]]) dfs(langs[L][i]);
			langs[L].pop_back();
		}
	}
}

int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	int N, M; cin >> N >> M;
	visited.resize(N);
	langs.resize(M);
	speaks.resize(N);

	F0R(i, N) {
		int K; cin >> K;
		F0R(j, K) {
			int L; cin >> L; --L;
			langs[L].push_back(i);
			speaks[i].push_back(L);
		}
	}

	int comp = 0;
	F0R(i, N) if (!visited[i]) ++comp, dfs(i);
	print((comp==1) ? "YES" : "NO");
}

