			return;;
		}
		used[v] = true;
		for (int to: g[v]) {
			dfs(to);
		}
	}
	void solve(std::istream& in, std::ostream& out) {
		int n, m;
		in >> n >> m;
		g.resize(n + m);
		used.resize(n + m);

		for (int i: range(n)) {
			int k;
			in >> k;
			for (int j: range(k)) {
				int a = i + m;
				int b;
				in >> b;
				g[a].push_back(b);
				g[b].push_back(a);
			}
		}

		dfs(m);

		for (int i: range(m, m + n)) {
			if (!used[i]) {
				out << "NO";
				return;
			}
		}
		out << "YES\n";
	}
};


int main() {
	std::ios_base::sync_with_stdio(false);
	TaskC solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	in.tie(nullptr);
	out << std::fixed;
	out.precision(20);
	solver.solve(in, out);
	return 0;
}

