class UnionFind
{
    vector<int> par, rank, sz;

public:
	UnionFind(int n){
        par.resize(n);
        rank.resize(n);
        sz.resize(n);
		for (int i = 0; i < n; i++){
			par[i] = i;
			rank[i] = 0;
			sz[i] = 1;
		}
	}

	int find(int x){
		if (x == par[x]) return x;
		else return par[x] = find(par[x]);
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (rank[x] < rank[y]){
			par[x] = y;
			sz[y] += sz[x];
		}
		else{
			par[y] = x;
			sz[x] += sz[y];
			if (rank[x] == rank[y]) rank[x]++;
		}
	}

	int size(int x){
		return sz[find(x)];
	}

	bool same(int x, int y){
        return find(x) == find(y);
    }
};

