class UFTree
{
    vector<int> parent;
    vector<int> height;
    vector<size_t> _size;

public:
    UFTree(int size)
    {
        for (int i = 0; i < size; i++)
        {
            parent.push_back(i);
            height.push_back(0);
            _size.push_back(1);
        }
    }
    int root(int node)
    {
        if (parent[node] == node)
        {
            return node;
        }
        return parent[node] = root(parent[node]);
    }
    void merge(int n0, int n1)
    {
        int r0 = root(n0), r1 = root(n1);
        if (r0 == r1)
        {
            return;
        }
        if (height[r0] < height[r1])
            swap(r0, r1);
        if (height[r0] == height[r1])
            height[r0]++;
        parent[r1] = r0;
        _size[r0] += _size[r1];
    }
    size_t size(int node)
    {
        return _size[root(node)];
    }
};

