		cin >> k;
		for (int x = 0; x < k; x++) {
			cin >> l[x];
			reached[l[x]] = false;
		}
		sort(l, l + k);

		for (int dist = 0; dist < k-1; dist++) {
			for (int sorce = dist + 1; sorce < k; sorce++) {
				int x = l[dist];
				int y = l[sorce];
				oks[x].push_back(y);
			}
		}
	}

	int lim_size = 0;

	for (int i = 1; i <= m; i++) {
		if (reached[i] == false) {
			lim_size++;
			sort(begin(oks[i]), end(oks[i]));
			oks[i].erase(unique(oks[i].begin(), oks[i].end()), oks[i].end());
		}
	}

	queue<int> queue;

	for (int i = 1; i <= m; i++) {

		if (reached[i] == false) {
			queue.push(i);
			reached[i] = true;
			break;
		}
