struct union_find {
	std::vector<long long> parent; // 頂点 i の直接の親
	std::vector<long long> size; // 頂点 i を含む連結成分の頂点数
	long long m; // 連結成分の数

	union_find(long long n) {
		for (long long i = 0; i < n; i++) {
			parent.push_back(i);
			size.push_back(1);
		}
		m = n;
	}

	long long root_of(long long n) {
		if (parent[n] == n) return n;
		return parent[n] = root_of(parent[n]); //パス圧縮
	}

	long long size_of(long long n) {return size[root_of(n)];}

	bool is_united(long long a, long long b) {return (root_of(a) == root_of(b));}

	void unite(long long a, long long b) {
		if (is_united(a, b)) return;
		m--;
		if (size_of(a) < size_of(b)) std::swap(a, b); //マージテク
		size[root_of(a)] += size_of(b);
		parent[root_of(b)] = root_of(a);
	}
};

