struct UnionFind
{
    vector<int> rank;
    vector<int> parent;
    const int n;
    UnionFind(int _n) :n(_n)
    {
        rank.assign(n, 1);
        parent.assign(n, -1);
    }

    int find(int node)
    {
        assert (node < n);

        if (parent[node] == -1)
            return node;
        else
            return parent[node] = find(parent[node]);
    }

    void unite(int i, int j)
    {
        i = find(i);
        j = find(j);

        if (i == j)
            return;

        if (rank[i] == rank[j])
        {
            parent[j] = i;
            rank[i]++;
        }
        else
        {
            if (rank[i] > rank[j]) swap(i, j);
            parent[j] = i;
        }
    }

    bool is_same(int i, int j)
    {
        return find(i) == find(j);
    }
};

