const int MAX = 1e7 ;

class UFT{
	public :
	int par[MAX] ;
	int rank[MAX] ;
	int size[MAX] ;
	bool root[MAX] ;
	int group ;
	int tree ;

	void init(int n){
		for(int i=0;i<n;i++){
			par[i] = i ;
			size[i] = 1 ;
			rank[i] = 0 ;
			root[i] = true ;
		}
		group = n ;
		tree = n ;
	}

	int find(int x){
		if(x==par[x]) return x ;
		else return par[x] = find(par[x]) ;
	}

	bool same(int x,int y){
		return find(x)==find(y) ;
	}

	void unite(int x,int y){
		x = find(x) ;
		y = find(y) ;
		if(x==y){
			if(root[x]){
				root[x] = false ;
				tree-- ;
			}
		}else{
			if(rank[x]==rank[y]){
				rank[x]++ ;
				par[y] = x ;
				size[x] += size[y] ;
				root[y] = false ;
				if(root[x]){
					tree-- ;
				}
			}else if(rank[x]>rank[y]){
				par[y] = x ;
				size[x] += size[y] ;
				root[y] = false ;
				if(root[x]){
					tree-- ;
				}
			}else{
				par[x] = y ;
				size[y] += size[x] ;
				root[x] = false ;
				if(root[y]){
					tree-- ;
				}
			}
			group-- ;
		}
	}
} ;

