using namespace std;
class Trees{
  vector<int> par;
  vector<int> rank;
  public:
  int root(int i){
    int rt;
    if(par[i]==i){rt=i;rank[i]=1;}
    else{rt=root(par[i]);par[i]=rt;rank[i]=2;}
    return rt;
  }
  void unite(int i,int j){
    int rki=rank[i];int rkj=rank[j];
    if(rki<rkj){par[root(i)]=root(j);rank[i]++;}
    else{par[root(j)]=root(i);rank[j]++;}
  }
  bool same(int i,int j){
    return root(i)==root(j);
  }
  Trees(int n){
    for(int i=0;i<n;i++) {par.push_back(i);rank.push_back(1);};
  }
  bool solve(long N){
    bool r=1;
    for(long i=1;i<N;i++)r&=same(0,i);
    return r;
  }
};
int main(){
  long N,M;cin>>N>>M;
  Trees tree(N+M);//人と言語
  for(long i=0;i<N;i++){
    long k;cin>>k;
    for(long j=0;j<k;j++){
      long l;cin>>l;tree.unite(i,N+l-1);
    }
  }
  cout<<(tree.solve(N)?"YES":"NO");
}

