void Connect(int x,int y){
    int p1,p2;

    p1 = rootOf(x);
    p2 = rootOf(y);

    if (p1 == p2) return;

    if(Size[p1] > Size[p2]) {
        Par[p2] = p1;
        Size[p1] += Size[p2];
    }
    else {
        Par[p1] = p2;
        Size[p2] += Size[p1];
    }
}
int rootOf(int x){
    int p = x;
    vector<int> t;

    while(Par[p] != p){
        t.push_back(p);
        p = Par[p];
    }

    for(auto s : t){
        Par[s] = p;
    }

    return p;
}

