class UnionFind {
public:
	UnionFind(int n) {
		depth.resize(n, 0);
		for (int j = 0; j < n; j++)
			parent.push_back(j);
		num.resize(n, 1);
	}

	void unite(int a, int b) {
		int ra = find(a);
		int rb = find(b);
		int da = depth[ra];
		int db = depth[rb];

		if (ra == rb)
			return;

		if (da > db) {
			parent[rb] = ra;
			num[ra] += num[rb];
		}
		else {
			parent[ra] = rb;
			num[rb] += num[ra];
			if (da == db)
				depth[rb] += 1;
		}

	}
	int getNum(int i) {
		int r = find(i);
		return num[r];
	}

	bool same(int a, int b) {
		return find(a) == find(b);
	}

	int find(int x) {
		int r = parent[x];
		if (x == r)
			return x;

		return parent[x] = find(r);
	}
private:
	int n;
	vector<int> parent;
	vector<int> depth;
	vector<int> num;
};



