struct UnionFind {
	vector<int> parent, size;

	UnionFind(int n) : parent(n), size(n, 1) {
		for (int i = 0; i < n; i++) {
			parent[i] = i;
		}
	}

	int operator[](int x) {
		if (parent[x] == x) return x;
		return parent[x] = operator[](parent[x]);
	}

	bool merge(int x, int y) {
		x = operator[](x);
		y = operator[](y);
		if (x == y) return false;
		if (size[x] < size[y]) swap(x, y);
		parent[y] = x;
		size[x] += size[y];
		return true;
	}
};

bool solve() {
	int n, m;
	cin >> n >> m;
	UnionFind uf(n + m);
	for (int i = 0; i < n; i++) {
		int k;
		scanf("%d", &k);
		for (int j = 0; j < k; j++) {
			int l;
			scanf("%d", &l);
			l--;
			uf.merge(i, n + l);
		}
	}
	for (int i = 0; i < n; i++) {
		if (uf[i] != uf[0]) return false;
	}
	return true;
}

int main() {
	puts(solve() ? "YES" : "NO");
}

