#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
class Union_Find {
private:
public:
    std::vector<int> par;
    std::vector<int> rank;

    Union_Find(int n) { // 初期化: O(n)
	par = rank = std::vector<int>(n);
	for(int i=0; i<n; i++) {
	    par[i]  = i;
	    rank[0] = 0;
	}
    }

    int root(int x) { // 木の根を求める: O(α(n)) 
	if(par[x] == x) return x;
	return par[x] = root(par[x]); // 親を辿りながら根に付け替える
    }

    void unite(int x, int y) { // x,yを含む集合を結合: O(α(n)) 
	x = root(x); y = root(y);
	if( x == y ) return;

	if( rank[x] < rank[y] ) par[x] = y;
	else {
	    par[y] = x;
	    if( rank[x] == rank[y] ) rank[x]++;
	}
    }

    bool same(int x, int y) { //x,yが同じ集合に含まれるかどうか: O(α(n)) 
	return root(x) == root(y);
    }
};

int main () {

    int N,M;
    cin >> N >> M;

    // 言語 i を話せる人集合 : g[i]
    vector<vector<int>> g(M);
    for(int i=0; i<N; i++) {
	int K; cin >> K;
	for (int j=0; j<K; ++j) {
	    int in; cin >> in; in--; // 0-index
	    assert(0<=in and in<M);
	    g[in].push_back(i);
	}
    }
    Union_Find uf(N);
    // 同じ言語が話せる人はマージ
    for(int i=0; i<M; i++) {
	for(int j=0; j<g[i].size(); j++) { 
	    uf.unite(g[i][0], g[i][j]);
	}
    }

    // 全員同じ集合ならYES
    bool ans = true;
    for(int i=0; i<N; i++) {
	cout << uf.par[i] << " " ;
	if( uf.par[0] != uf.par[i] ) {
	    ans = false;
	}
    }
    if(ans) cout << "YES" << endl;
    else    cout << "NO" << endl;

    return 0;
}

