int root(int v,int* uf){
  if(uf[v]<0)return v;
  int u=root(uf[v],uf);
  uf[v]=u;
  return u;
}

void merge(int u,int v,int* uf){
  u=root(u,uf);v=root(v,uf);
  if(u==v)return;
  int w=(uf[u]<uf[v])?u:v;
  uf[w]--;
  uf[u+v-w]=w;
}

