int getroot(int n){
  while(parent[n]!=n){
    n=parent[n];
  }
  return n;
}

bool samegroup(int n, int m){
  int nroot = getroot(n);
  int mroot = getroot(m);
  return nroot==mroot;
}

void unite(int n, int m){
  if (samegroup(n, m)) return;
  int nroot=getroot(n);
  int mroot=getroot(m);
  if (length[nroot]>length[mroot]){
    parent[mroot]=nroot;
  } else if (length[mroot]>length[nroot]){
    parent[nroot]=mroot;
  } else {
    parent[mroot]=nroot;
    length[nroot]++;
  }
  return;
}

