class UnionFind {
public:
	vector <lint> par; // 各元の親を表す配列
	vector <lint> siz; // 素集合のサイズを表す配列(1 で初期化)

	// Constructor
	UnionFind(lint sz_) : par(sz_), siz(sz_, 1ll) {
		for (lint i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
	}
	void init(lint sz_) {
		par.resize(sz_);
		siz.assign(sz_, 1ll);  // resize だとなぜか初期化されなかった
		for (lint i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
	}

	// Member Function
	// Find
	lint root(lint x) { // 根の検索
		while (par[x] != x) {
			x = par[x] = par[par[x]]; // x の親の親を x の親とする
		}
		return x;
	}

	// Union(Unite, Merge)
	bool merge(lint x, lint y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		// merge technique（データ構造をマージするテク．小を大にくっつける）
		if (siz[x] < siz[y]) swap(x, y);
		siz[x] += siz[y];
		par[y] = x;
		return true;
	}

	bool issame(lint x, lint y) { // 連結判定
		return root(x) == root(y);
	}

	lint size(lint x) { // 素集合のサイズ
		return siz[root(x)];
	}
};

