	UnionFind tree(N);
	REP(i, N) {
		cin >> K;
		REP(j, K) {
			cin >> L; L--;
			to[L].push_back(i);
		}
	}
	REP(i, M) {
		REP(j, SZ(to[i]) - 1) {
			if (!tree.issame(to[i][j], to[i][j + 1])) {
				tree.merge(to[i][j], to[i][j + 1]);
			}
		}
	}
	REP(i, N - 1) {
		if (!tree.issame(i, i + 1)) {
			cout << "NO" << endl;
			return 0;
		}
	}
	cout << "YES" << endl;
}

