//Union-Find Tree
class UnionFind{
public:
    int N;              //頂点数
    int groupnum;       //グループの総数
    vector<int> par;    //par[i]:iの親の番号
    vector<int> size;   //size[i]:iが属するグループと同じグループに属する頂点数
    vector<int> rank;   //ランク

    UnionFind(int n) : N(n), groupnum(n), par(n), size(n, 1), rank(n, 0){  //初期化時はすべて根とする
        for(int i=0; i<n; i++){
            par[i] = i;
        }
    }

    int root(int x){    //データxが属する木の根を再帰で得る
        if(par[x] == x){
            return x;
        }else{
            return par[x] = root(par[x]); //経路圧縮を同時に実行
        }
    }

    void unite(int x, int y){   //xの属する木とyの属する木を併合
        int rx = root(x), ry = root(y);
        if(rx == ry) return;    //xとyの属する木が同じなら何もしない

        if(rank[rx] < rank[ry]) swap(rx, ry);   //rank[rx] >= rank[ry]とする

        par[ry] = rx;   //yの木の根をxの根につける

        if(rank[rx] == rank[ry]) rank[rx]++;    //rankを更新
        size[rx] += size[ry];   //sizeを更新

        groupnum--;     //グループの総数は1減る
    }

    int getSize(int x){         //xの属する木のサイズを返す
        return size[x] = size[root(x)];
    }

    bool same(int x, int y){    //x,yが同じ木に属するときtrue, そうでなければfalse
        return root(x) == root(y);
    }
};


//Weighted Union-Find Tree
class WeightedUnionFind : public UnionFind{
public:
    vector<ll> weight;  //差分重み

    WeightedUnionFind(int n) : UnionFind(n){
        weight.resize(n, 0);
    }

    int root(int x){    //差分重みも同時に更新する
        if(par[x] == x){
            return x;
        }else{
            int r = root(par[x]);
            weight[x] += weight[par[x]];    //  累積和
            return par[x] = r;  //経路圧縮
        }
    }

    ll getWeight(int x){    //xのrootからの差分重みを取得
        root(x);
        return weight[x];
    }

    ll diff(int x, int y){  //yとxの差分を取得
        return getWeight(y) - getWeight(x);
    }

    //weight(y) - weight(x) = w となるようにマージ
    bool unite(int x, int y, ll w){
        w -= diff(x, y);    //rootとの重み差分を補正

        int rx = root(x), ry = root(y);
        if(rx == ry) return false;  //xとyがすでにマージされていたらfalseを返す

        if(rank[rx] < rank[ry]){    //rank[rx] >= rank[ry]とする
            swap(rx, ry);
            w *= -1;                //合わせてwも符号反転
        }

        par[ry] = rx;   //yの木の根をxの根につける

        if(rank[rx] == rank[ry]) rank[rx]++;    //rankを更新
        size[rx] += size[ry];   //sizeを更新

        groupnum--;     //グループの総数は1減る

        weight[y] = w;  //xとyの差分をweight[y]に記録

        return true;
    }
};


signed main(){
    int n, m;
    cin >> n >> m;

    UnionFind UF(n);
    vector<int> v(m, -1);

    REP(i, n){
        int k;
        cin >> k;
        REP(j, k){
            int a;
            cin >> a;
            if(v[a-1] == -1) v[a-1] = i;
            else UF.unite(v[a-1], i);
        }
    }

    cout << (UF.getSize(0) == n ? "YES": "NO") << endl;

}

