int main()
{
    int N, M;
    cin >> N >> M;

    vector<vector<int>> edge(N + M);
    for (int i = 0; i < N; i++)
    {
        int K;
        cin >> K;
        for (int j = 0; j < K; j++)
        {
            int L;
            cin >> L;
            L--;
            edge[i].push_back(N + L);
            edge[N + L].push_back(i);
        }
    }

    vector<bool> is_visited(N, false);
    queue<int> q;
    q.push(0);
    while (!q.empty())
    {
        int from = q.front();
        q.pop();
        if (is_visited[from])
        {
            continue;
        }
        else
        {
            is_visited[from] = true;
        }

        for (int to : edge[from])
        {
            if (!is_visited[to])
            {
                q.push(to);
            }
        }
    }

    for (int i = 0; i < N; i++)
    {
        if (!is_visited[i])
        {
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;
}

