class UnionFind{
public:
  int par[MAX_N];
  int cnt[MAX_N];
  UnionFind()
  {
    init();
  }
  void init()
  {
    memset(par, 0, sizeof(par));
    memset(cnt, 0, sizeof(cnt));
    for (size_t i = 0; i < MAX_N; i++) {
      par[i] = i;
    }
    for (size_t i = 0; i < N; i++) {
      cnt[L[i][0]]++;
    }
  }
  int find(int x)
  {
    if(x == par[x]){
      return x;
    }
    else{
      return par[x] = find(par[x]);
    }
  }
  void unite(int x, int y)
  {
    x = find(x);
    y = find(y);
    if(x == y){
      return;
    }
    par[x] = y;
    cnt[y] += cnt[x];
  }
  bool same(int x, int y)
  {
    return find(x) == find(y);
  }
  int size(int x)
  {
    return cnt[find(x)];
  }
}unionFind;

