class UnionFindTree
{
  public:
	int treeCnt; //ツリーの数
	vi rank, p;  //rank => 根の高さ, p => 親
	vi num;		 //木の要素数
	vi diff_weight;
	UnionFindTree() {}
	UnionFindTree(int size)
	{
		rank.resize(size, 0);
		p.resize(size, 0);
		num.assign(size, 1);
		treeCnt = 0;
		REP(i, size)
		{
			makeset(i);
		}
	}

	void makeset(int x)
	{
		p[x] = x;
		rank[x] = 0;
		treeCnt++;
	}

	//同じ木に属しているか判定
	bool isSame(int x, int y)
	{
		return root(x) == root(y);
	}

	//xとyが属している木をつなぐ
	void unite(int x, int y)
	{
		link(root(x), root(y));
	}

	//木と木を繋ぐ処理をする。
	void link(int x, int y)
	{
		if (!isSame(x, y))
		{
			if (rank[x] > rank[y])
			{
				p[y] = x;
				num[x] += num[y];
			}
			else
			{
				p[x] = y;
				if (rank[x] == rank[y])
				{
					rank[y]++;
				}
				num[y] += num[x];
			}
			treeCnt--;
		}
	}

	//xが属している木の根を探る
	int root(int x)
	{
		if (p[x] == x)
			return x;
		else
			return p[x] = root(p[x]);
	}

	int countTree()
	{
		return treeCnt;
	}

	int getNum(int a)
	{
		return num[root(a)];
	}
};

