int N, M;
vector <int> L[int(1e5 + 5)], P[int(1e5 + 5)];
bool L_v[int(1e5 + 5)], P_v[int(1e5 + 5)];

int main(){
  scanf("%d%d", &N, &M);
  for (int i = 1; i <= N; i++){
    int K; scanf("%d", &K);
    for (int j = 0; j < K; j++){
      int l; scanf("%d", &l);
      L[l].push_back(i);
      P[i].push_back(l);
    }
  }

  queue <int> que; que.push(1);
  P_v[1] = true;
  while (!que.empty()){
    int Q = que.front(); que.pop();

    for (int i = 0; i < P[Q].size(); i++){
      int L_next = P[Q][i];
      if (L_v[L_next]) continue;
      L_v[L_next] = true;
      for (int j = 0; j < L[L_next].size(); j++){
        int P_next = L[L_next][j];
        if (P_v[P_next]) continue;
        P_v[P_next] = true;
        que.push(P_next);
      }
    }
  }

  for (int i = 1; i <= N; i++){
    if (!P_v[i]){
      NO(); return 0;
    }
  }
  YES();


  return 0;
}

