using namespace std;

class UnionFind {
public:
    UnionFind(int64_t n) {
        //parが負の場合、このグループに属するノードの数 * (-1)を示す
        par_.resize(n, -1);
    }

    //根を求める
    int64_t root(int64_t x) {
        return (par_[x] < 0 ? x : par_[x] = root(par_[x]));
    }

    //xとyの属する集合を併合
    void unite(int64_t x, int64_t y) {
        x = root(x);
        y = root(y);
        if (x == y) {
            return;
        }

        //要素数を足す(負の数だがそのまま足せば良い)
        par_[x] += par_[y];

        //yをxに繋げる
        par_[y] = x;
    }

    //xとyが同じ集合に属するか否かを判定
    bool same(int64_t x, int64_t y) {
        return (root(x) == root(y));
    }

    int64_t size(int64_t x) {
        x = root(x);
        return -par_[x];
    }
private:
    vector<int64_t> par_;
};

int main() {
    int64_t N, M;
