        cin >> K;
        L[i].resize(K);
        for (int64_t j = 0; j < K; j++) {
            cin >> L[i][j];
            L[i][j]--;
        }
    }

    //各言語から見てそれを何人目の人が話せるか
    vector<vector<int64_t>> speakable(M);
    for (int64_t i = 0; i < N; i++) {
        for (int64_t l : L[i]) {
            speakable[l].push_back(i);
        }
    }

    UnionFind uf(N);

    for (int64_t l = 0; l < M; l++) {
        //先頭の人につなぐ
        for (int64_t j = 1; j < speakable[l].size(); j++) {
            uf.unite(speakable[l][0], speakable[l][j]);
        }
    }

    cout << (uf.size(0) == N ? "YES" : "NO") << endl;
}

