  {
    init(n);
  }

  void init(int n) // 初期化
  {
    par.resize(n);
    sz.resize(n);
    REP(i, n)
    {
      par[i] = i;
      sz[i] = 1;
    }
  }

  int find(int x) // 木の根を求める
  {
