int N, M, K, L;
int parent[200005];
int power[200005];

void initset(int n){
    for (int i=1;i<=n;i++){
        parent[i] = i;
        power[i] = 0;
    }
}

int root (int x ) {
    if ( x == parent [ x ]) return x ;
        return parent[x] = root ( parent [x]) ; //path compression
}
bool is_connected ( int x , int y ) {
    return root ( x ) == root ( y ) ;
}

void connect ( int x , int y ) {
    int root_x = root ( x );
    int root_y = root ( y );
    if (power[root_x] > power[root_y]) parent[root_y] = root_x;
    else {parent[root_x] = root_y; if (power[root_x] == power[root_y]) power[root_y]++;}
}

