using namespace std;

int par[10005];
// par[i] is the 'parent' of item i
// i -> par[i]
int sz[10005];
// sz[i] stores the number of items in group i

// this function initializes the UFDS
void ufds_init(int n) {
	for (int i = 0; i <= n; i++) {
		par[i] = i;
		sz[i] = 1;
	}
}

//  this function returns the representative of the group that item x is in
int ufds_find(int x) {
	if (par[x] == x) {
		return x;
	}
	else {
		// path compression: link x -> representative of the group directly
		// recursively follow the arrows up to the representative
		par[x] = ufds_find(par[x]);
		return par[x];
	}
}

// this function combines the groups items x and y are in
void ufds_merge(int x, int y) {
	// find the representatives of the two groups
	x = ufds_find(x);
	y = ufds_find(y);
	// union by size: link rep of smaller group to rep of larger group
	if (sz[x] < sz[y]) {
		par[x] = y; // x -> y
		sz[y] += sz[x]; // number of items in group y has increased by the number of items in group x
	}
	else {
		par[y] = x; // y -> x
		sz[x] += sz[y];
	}
}

// this function returns the size of the group item x is in
int ufds_get_size(int x) {
	return sz[ufds_find(x)];
}

// this function returns true if items x and y are in the same set
bool ufds_is_same_set(int x, int y) {
	return ufds_find(x) == ufds_find(y);
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	int n, m;
	cin >> n >> m;
	ufds_init(n);
	vector<set<int>> langs(n);

	for (int i = 0; i < n; i++) {
		int k;
		cin >> k;
		for (int j = 0; j < k; j++) {
			int l;
			cin >> l;
			bool found = false;
			// Look for people who speak l too, but we really only need one
			for (int k = 0; k < i; k++) {
				if (langs[k].find(l) != langs[k].end()) {
					ufds_merge(i, k);
					found = true;
					break;
				}
			}
			// If no one, add it to our list
			if (!found) {
				langs[i].insert(l);
			}
		}
	}
	int common_parent = ufds_find(0);
	for (int i = 1; i < n; i++) {
		if (ufds_find(i) != common_parent) {
			cout << "NO";
			return 0;
		}
	}
	cout << "YES";
}

