struct UF{
  vector<int>rank,pars;
  UF(int n){
    rank.resize(n,0);
    pars.resize(n);
    for(int i=0;i<n;i++)pars[i]=i;
  }
  int root(int x){
    if(pars[x]!=x)return root(pars[x]);
    else return x;
  }
  bool same(int x,int y){
    return root(x)==root(y);
  }
  void unite(int x,int y){
    x=root(x);
    y=root(y);
    if(x==y)return;
    if(rank[x]>rank[y]){
      pars[y]=x;
    }
    else{
      pars[x]=y;
      if(pars[x]==pars[y])rank[x]++;
    }
  }
};

int main(){
  int N,M;
  cin>>N>>M;
  UF uf(N+M);
  for(int i=0;i<N;i++){
    int k;
    cin>>k;
    for(int j=0;j<k;j++){
      int l;
      cin>>l;
      uf.unite(i,l+N-1);
    }
  }
  bool ok=true;
  for(int i=0;i<N;i++){
    if(!uf.same(i,1))ok=false;
  }
  if(ok)cout<<"YES"<<endl;
  else cout<<"NO"<<endl;
  return 0;
}

