struct UnionFind {
  vector<ll> parents;

  UnionFind(ll n) : parents(vector<ll>(n, -1)) {}

  ll root(ll a) {
    if (parents[a] < 0) {
      return a;
    }

    auto r = root(parents[a]);
    parents[a] = r;
    return r;
  }

  bool same(ll a, ll b) { return root(a) == root(b); }

  void merge(ll a, ll b) {
    ll ar = root(a);
    ll br = root(b);

    if (ar == br) {
      return;
    }

    // make less index one as a root
    if (ar > br) {
      swap(ar, br);
    }

    parents[ar] += parents[br];
    parents[br] = ar;
  }

  ll size(ll a) { return -parents[a]; }

  ll group_count() {
    ll res = 0;

    for (auto s : parents) {
      if (s < 0) {
        res++;
      }
    }

    return res;
  }
};

void solve() {
  ll N, M;
  cin >> N >> M;

  UnionFind uf(N);

  VL lang_to_person(M, -1);

  rep(i, N) {
    ll K;
    cin >> K;

    rep(j, K) {
      ll L;
      cin >> L;
      L--;

      if (lang_to_person[L] != -1) {
        uf.merge(i, lang_to_person[L]);
      } else {
        lang_to_person[L] = i;
      }
    }
  }

  if (uf.group_count() == 1) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
}

