typedef struct{ int to, cost; }Edge;
class Dijkstra{
    int V;
    vector< vector<Edge> > G;
    vector<int> d;
public:
    Dijkstra(int _V){
        V=_V;
        G.resize(V+10);
        d.resize(V+10);
    }
    void add_edge_oneway(int a, int b, int c){
        Edge e;
        e.to=b; e.cost=c;
        G[a].push_back(e);
    }
    void add_edge_twoway(int a, int b, int c){
        Edge e1,e2;
        e1.to=b; e1.cost=c; e2.to=a; e2.cost=c;
        G[a].push_back(e1);
        G[b].push_back(e2);
    }
    void init(int s){
        priority_queue< pair<int,int>,vector< pair<int,int> >, greater< pair<int,int> > > que;
        for(int i=0;i<V+10;i++)d[i]=1e9+7;
        d[s]=0;
        que.push(make_pair(0,s));
        while(!que.empty()){
            pair<int,int> p=que.top(); que.pop();
            int v=p.second;
            if(d[v]<p.first)continue;
            for(int i=0;i<G[v].size();i++){
                Edge e=G[v][i];
                if(d[e.to]>d[v]+e.cost){
                    d[e.to]=d[v]+e.cost;
                    que.push(make_pair(d[e.to],e.to));
                }
            }
        }
    }
    int dist(int a){
        return d[a];
    }
};


