        par[x] += par[y];
        par[y] = x;
        w[x] += w[y];
        ++w[x];
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }

    int wei(int x) {
        return w[root(x)];
    }
};

void solve() {
	int n, m; cin >> n >> m;
	UnionFind uf(n + m);
	rep(i, n) {
		int k; cin >> k;
		rep(j, k) {
			int l; cin >> l; --l;
			uf.merge(i, n + l);
		}
	}
	int r = uf.root(0);
	rep(i, n) {
		if(!uf.issame(i, r)) {
			cout << "NO" << endl;
            return;
		}
	}
	cout << "YES" << endl;
}

