struct UnionFind {
    vector<int> root;

    UnionFind(int n) {
        root.assign(n,-1);
    }

    int find(int n){
        if(root[n] < 0) return n;
        else return root[n] = find(root[n]);
    }

    void connect(int a,int b){
        int ar = find(a);
        int br = find(b);
        if(ar == br) return;

        if(-root[ar] < -root[br]){
            root[br] += root[ar];
            root[ar] = br;
        }else{
            root[ar] += root[br];
            root[br] = ar;
        }
    }
};

