        for (int j = 0; j < K; j++) {
            int L;
            cin >> L;
            v[L - 1].push_back(i);
        }
    }
    UnionFind tree(N);
    for (int i = 0; i < M; i++) {
        if (v[i].size() <= 1) continue;
        int l = v[i][0];
        for (const auto& x : v[i]) tree.unite(l, x);
    }
    if (tree.tsize(0) == N)
        cout << "YES" << endl;
    else
        cout << "NO" << endl;
    return 0;
}

