    // 2. 空のキュー.
    queue<int> q;

    // 3. 参加者 m をキュー q に追加.
    memo[m] = l;
    q.push(m);
    while(!q.empty()){

        // 4. キューから取り出す.
        int u = q.front();
        q.pop();

        // 5. 取り出した要素を処理.
        for(auto &e : graph[u]){
             // 6. 訪問済であれば, 処理をスキップ.
            if(memo[e] > 0)            continue;
            if(memo[e] == 0 && e != m) memo[e] = l, q.push(e);
        }
    }
    return;
}

int main(){

    // 1. 入力情報.
    int N, M;
    scanf("%d %d", &N, &M);

    // 2. 言語ごとに, 参加者情報を保存.
    rep(i, N){
        int K, L;
        scanf("%d", &K);
        rep(j, K) scanf("%d", &L), L--, member[L].pb(i);

    }
    rep(i, M){
        for(auto &p : member[i]){
            int f = member[i].front();
            if(f != p) graph[f].insert(p), graph[p].insert(f);
        }
    }
    // rep(i, N){
    //     for(auto &p : graph[i]) printf("i=%d p=%d\n", i, p);
    // }

    // 4. 連結成分の個数をカウント.
    int ans = 1;
    rep(i, N) if(memo[i] == 0) bfs(i, ans), ans++;
    // rep(i, N) printf("%d ", memo[i]);
    // printf("\n");

    // 5. 出力.
    printf("%s\n", (ans == 2) ? "YES" : "NO");
    return 0;

}

