template <int MAX_N>
class UnionFind {
public:
    int parent[MAX_N];
    int rank[MAX_N];
    int size[MAX_N];

    UnionFind(int n) {
        for (int j = 0; j < n; ++j) {
            parent[j] = j; rank[j] = 0;
            size[j] = 1;
        }
    }

    int find(int x) {
        if (parent[x] == x) { return x; }
        return parent[x] = find(parent[x]);
    }

    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) { return false; }

        if (rank[x] < rank[y]) {
            parent[x] = y;
            size[y] += size[x];
        } else {
            parent[y] = x;
            if (rank[x] == rank[y]) {
                ++rank[x];
            }
            size[x] += size[y];
        }

        return true;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

