using namespace std;

class DisjointSet {
private:
	vector<int> rank, size, p;
	int num = 0;
public:
	DisjointSet() {}
	DisjointSet(int n) {
		num = n;
		rank.assign(n, 0);
		size.assign(n, 1);
		p.assign(n, 0);
		for (int i = 0; i < n; i++) p[i] = i;
	}

	bool same(int x, int y) {
		return root(x) == root(y);
	}

	void unite(int x, int y) {
		x = root(x), y = root(y);
		if (x == y) return;
		num--;
		if (rank[x] > rank[y]) {
			p[y] = x;
			size[x] += size[y];
		} else {
			p[x] = y;
			size[y] += size[x];
			if (rank[x] == rank[y]) rank[y]++;
		}
	}

	int root(int x) {
		return p[x]==x?x:p[x]=root(p[x]);
	}

	int forest_size() {
		return num;
	}
};

int main() {
	int N,M; cin >> N >> M;
	DisjointSet dj(N);
	for(int i=0;i<N;++i) {
		int K; cin >> K;
		int prev; cin >> prev;
		while(--K) {
			int L; cin >> L;
			dj.unite(prev-1,L);
			prev=L;
		}
	}
	if(dj.forest_size()==1) cout << "YES" << endl;
	else cout << "NO" << endl;

	return 0;
}

