            langs.unite(native_lang[i], l);
        }
    }
    for (int i = 0; i < n - 1; i++) {
        if (!langs.isSame(native_lang[i], native_lang[i + 1])) {
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;
}

