bool is_2bu_graph(vector< vector<ll> >& G, ll now, ll col) {
    color[now] = col;
    for(auto g : G[now]) {
        if(color[g] != -1) {
            if(color[g] == col) return false;
            else continue;
        } else {
            if(!is_2bu_graph(G, g, 1-col)) return false;
