class UnionFind {
public:
    int n;
    VI roots, ranks, cnts;
    UnionFind(int n_) : n(n_), roots(n_), ranks(n_), cnts(n_, 1) {
        iota(ALL(roots), 0);
    }

    int find(int v) {
        return roots[v] = roots[v] == v ? v : find(roots[v]);
    }

    bool same(int a, int b) {
        return find(a) == find(b);
    }

    int count(int v) {
        return cnts[find(v)];
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;

        if (ranks[a] < ranks[b]) {
            roots[a] = b;
            cnts[b] += cnts[a];
        } else {
            roots[b] = a;
            cnts[a] += cnts[b];
            if (ranks[a] == ranks[b]) ranks[a]++;
        }
    }
};

