    int group = uf.find(l[0][0]);
    for(int i = 1; i < n; ++i){
        if(uf.find(l[i][0]) != group){
            ok = false;
            break;
        }
    }

    if(ok)  cout << "YES\n";
    else    cout << "NO\n";
}

