	bool flag = false;
	for(int i = 0; i < lanlon[a]; i++){
		for(int j = 0; j < lanlon[b]; j++){
			if(c1[i] == c2[j]){
				flag = true;
				break;
			}
		}
		if(flag) break;
	}

	if(!flag) return false;

	for(int i = 0; i < c2.size(); i++){
		if(c2[i] == 0) break;
		if(!ch[c2[i] - 1]){
			ch[c2[i] - 1] = true;
			c1[ind] = c2[i];
			ind += 1;
		}
	}

	if(v[a] > v[b]){
		v[a] ^= v[b];
		v[b] ^= v[a];
		v[a] ^= v[b];
	}
	v[a] += v[b];
	v[b] = a;
	return true;
}

