#include <bits/stdc++.h>
using namespace std;

int parent[200005], ranks[200005];

void initset(int n) {
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        ranks[i] = 0;
    }
}

int findset(int x) {
    if (parent[x] == x) return x;
    parent[x] = findset(parent[x]); // path compression
    return parent[x];
}

bool sameset(int x, int y) {
    return findset(x) == findset(y);
}

void mergeset(int x, int y) {
    x = findset(x); // find representatives
    y = findset(y);
    if (ranks[x] > ranks[y]) {
        parent[y] = x;
    } else { // rank[x] <= rank[y]
        parent[x] = y;
        if (ranks[x] == ranks[y]) {
            ranks[y]++;
        }
    }
}

int N, M, K, L;

int main() {

    cin >> N >> M;
    initset(N+M+5); // 5 is a bit of buffer
    for (int i = 0; i < N; i++) {
        cin >> K;
        for (int j = 0; j < K; j++) {
            cin >> L;
            mergeset(i+1, N+L);
        }
    }

    for (int i = 1; i <= N; i++) {
        if (!sameset(i, 1)) {
            cout << "NO\n";
            return 0;
        }
    }

    cout << "YES\n";

}

