template<typename T>
void remove(std::vector<T>& vector, unsigned int index)
{
    vector.erase(vector.begin() + index);
}
int rootVal(int a, vector<int> &v){
	if(v[a] < 0) return v[a] * -1;
	return v[a] = rootVal(v[a], v);
}
int root(int a, vector<int> &v){
	if(v[a] < 0) return a;
	return v[a] = root(v[a], v);
}
bool connect(int a, int b, vector<int> &v, vector<int> &c1, vector<int> &c2, vector<bool> &ch, int &ind, vector<int> &lanlon, vector<int> &yet, int &l){
	a = root(a, v);
	b = root(b, v);
	if(a == b) return false;

	bool flag = false;
	for(int i = 0; i < lanlon[a]; i++){
		for(int j = 0; j < lanlon[b]; j++){
			if(c1[i] == c2[j]){
				flag = true;
				break;
			}
		}
		if(flag) break;
	}

	if(!flag) return false;

	remove(yet, l);
	l -= 1;

	for(int i = 0; i < lanlon[b]; i++){
		if(c2[i] == 0) break;
		if(!ch[c2[i] - 1]){
			ch[c2[i] - 1] = true;
			c1[ind] = c2[i];
			ind += 1;
			lanlon[a] += 1;
		}
	}

	if(v[a] > v[b]){
		v[a] ^= v[b];
		v[b] ^= v[a];
		v[a] ^= v[b];
	}
	v[a] += v[b];
	v[b] = a;
	return true;
}

int main() {
	int n, m;
	int ind;
	cin >> n >> m;
	vector<int> uf(n);
	vector<bool> ch(m);
	vector<int> lanlon(n);
	vector<int> yet;

	for(int i = 0; i < n; i++){
		uf[i] = -1;
	}

	vector<vector<int>>lang(n);
	for(int i = 0; i < n; i++){
		cin >> lanlon[i];
		lang[i] = vector<int>(lanlon[i]);
		if(i == 0){
			ind = lanlon[i];
			lang[i] = vector<int>(m);
		}else{
			yet.push_back(i);
		}
		for(int j = 0; j < lanlon[i]; j++){
			cin >> lang[i][j];
		}
	}

	for(int i = 0; i < m; i++){
		if(lang[0][i] == 0) break;
		ch[lang[0][i] - 1] = true;
	}

	while(1){
		bool flag = false;
		for(int i = 0; i < yet.size(); i++){
			flag = connect(0, yet[i], uf, lang[0], lang[i], ch, ind, lanlon, yet, i);
		}
		if(!flag) break;
	}

	if(rootVal(0, uf) == n){
		cout << "YES" << endl;
		return 0;
	}else{
		cout << "NO" << endl;
	}

	return 0;
}

