        }
    }

    void unite(int x,int y){
        x=find(x);
        y=find(y);
        if(x==y) return;

        groups--;
        if(rank[x]<rank[y]){
            par[x]=y;
            elm[y]+=elm[x];
        }else{
            par[y]=x;
            elm[x]+=elm[y];
            if(rank[x]==rank[y])rank[x]++;
        }
    }

    bool isSame(int x,int y){
        return find(x)==find(y);
    }
};



