const ll INF = 1001001001;
const ll MOD = 1000000007;

ll N, M, ans=0, tmp=0;
vector<vector<ll>> G, H;
vector<ll> d;

void bfs(ll id) {
    queue<ll> Q;
    Q.push(id);
    while(!Q.empty()) {
        ll num = Q.front();
        Q.pop();
        for(int i=0;i<H[num].size();i++) {
            if(d[H[num][i]]==INF) {
                d[H[num][i]]=0;
                Q.push(H[num][i]);
            }
        }
    }
}

signed main(){
    cin >> N >> M;
    G.resize(N+M);
    H.resize(N);
    for(int i=0;i<N;i++) {
        ll a;
        cin >> a;
        for(int j=0;j<a;j++) {
            ll l;
            cin >> l;
            l += N-1;
            G[i].push_back(l);
            G[l].push_back(i);
        }
    }
    for(int i=0;i<N;i++) {
        for(int j=0;j<G[i].size();j++) {
            for(int k=0;k<G[G[i][j]].size();k++) {
                H[i].push_back(G[G[i][j]][k]);
                H[G[G[i][j]][k]].push_back(i);
            }
        }
    }
    d.resize(N, INF);
    bfs(0);
    for(int i=0;i<N;i++) {
        ans = max(ans, d[i]);
    }
    if(ans==INF) cout << "NO" << endl;
    else cout << "YES" << endl;
    return 0;
}

