class UnionFind {
    public:
    int n;
    vector<int> par, rank;

    UnionFind(int n): n(n) {
        for(int i=0;i<n;++i) {
            par.push_back(i);
            rank.push_back(0);
        }
    }

    int find(int x) {
        return ((par[x] == x) ? x : par[x] = find(par[x]));
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);

        if(x == y) return;

        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
        return;
    }

    bool is_same(int x, int y) {
        return find(x) == find(y);
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, m, k, l;
    cin >> n >> m;
    vector<int> langs[m];
    for(int i=0;i<n;++i) {
        cin >> k;
        for(int j=0;j<k;++j) {
            cin >> l;
            --l;
            langs[l].push_back(i);
        }
    }

    UnionFind uf = UnionFind(n);
    for(int i=0;i<m;++i) {
        int ln = langs[i].size();
        for(int j=0;j<ln-1;++j) {
            uf.unite(langs[i][j], langs[i][j+1]);
        }
    }

    int root = uf.find(0);
    for(int i=1;i<n;++i) {
        if(root != uf.find(i)) {
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;
    return 0;
}

