struct uf
{
	vector<lint> p;
	vector<lint> s;

	uf(lint n) : p(n), s(n)
	{
		rep(i, n)
		{
			p[i] = i;
			s[i] = 1;
		}
	}

	lint rt(lint n)
	{
		return p[n] == n ? n : p[n] = rt(p[n]);
	}

	void un(lint n, lint m)
	{
		if (rt(n) != rt(m))
		{
			s[rt(m)] += s[rt(n)];
			p[rt(n)] = rt(m);
		}
	}

	bool eq(lint n, lint m)
	{
		return rt(n) == rt(m);
	}

	lint sz(lint n)
	{
		return s[rt(n)];
	}
};


int main()
{
	lint n, m;
	cin >> n >> m;

	uf t(n + m);

	rep(i, n)
	{
		lint k;
		cin >> k;

		rep(j, k)
		{
			lint l;
			cin >> l;
			l--;

			t.un(i, n + l);
		}
	}

	lint r0 = t.rt(0);
	rep(i, n)
	{
		if (t.rt(i) != r0)
		{
			cout << "NO" << endl;
			ret;
		}
	}

	cout << "YES" << endl;

	return 0;
}

