struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

int main(){
  int N, M;
  cin >> N >> M;
  vector<vector<int>> L(N);
  REP(i,N) {
    int K;
    cin >> K;
    REP(j,K) {
      int l;
      cin >> l; --l;
      L[i].push_back(l);
    }
  }

  vector<vector<int>> S(M);
  REP(i,N)REP(j,L[i].size()) {
    S[L[i][j]].push_back(i);
  }

  UnionFind uf(N);
  REP(i,M){
    REP(j,S[i].size()) uf.unionSet(S[i][0], S[i][j]);
  }
  if(uf.size(0) == N) cout << "YES" << endl;
  else cout << "NO" << endl;
  return 0;
}

