signed main()
{
    int n = in(), m = in();

    REP(i, n){
        int k = in();
        REP(j, k){
            int l = in();
            lang[l].pb(i);
            person[i].pb(l);
        }
    }

    queue<int> que;
    for (int i : person[0]){
        que.push(i);
    }
    set<int> talkable;
    while (not que.empty()){
        int l = que.front();
        que.pop();

        if (talked[l]) continue;
        talked[l] = true;
        set<int> tmp;

        for (int i : lang[l]){
            talkable.insert(i);
            for (int j : person[i]){
                if (not talked[j]) tmp.insert(j);
            }
        }
        for (int i : tmp){
            que.push(i);
        }
    }
    print(talkable.size() == n ? "YES" : "NO");

    return 0;
}

