  srep(i,M,M+N-1) {
    if(tree.root(i) != tree.root(i+1)) {
      ok = false;
      break;
    }
  }
  if(ok) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
  return 0;
}

