void rec(int curr, int prev, int depth)
{
  vis.insert(curr);
  if (depth == 3) return ;
  each (lang, part_2_lang[curr]) {
    each (next, lang_2_part[lang]) {
      if (prev == next) continue;
      rec(next, curr, depth + 1);
    }
  }
  return ;
}

