struct UnionFindTree {
	int n;
    int c;
	vector<int> p;

	UnionFindTree(int n): n(n), c(n), p(n, -1) {}

	int find(int x)
	{
		return (p[x] < 0 ? x : p[x] = find(p[x]));
	}

	void unite(int x, int y)
	{
		x = find(x); y = find(y);
		if (x == y) return;
		if (p[x] > p[y]) swap(x, y);
		p[x] += p[y];
		p[y] = x;
		c--;
	}

	bool same(int x, int y)
	{
		return find(x) == find(y);
	}

	// x を含む集合のサイズ
	int size(int x)
	{
		return -p[find(x)];
	}

	// 連結成分の個数
	int count()
	{
		return c;
	}
};
