      if(d[l]==0){
	d[l]=i;
      } else {
	unite(u,d[l],i);
      }
    }
  }
  for(i=1;i<=n;i++) if(!same(u,1,i)) break;
  printf("%s\n",i>n?"YES":"NO");
}

