#include <stdio.h>
#include <stdlib.h>

typedef struct ll{
  int *data;
  int num;
  struct ll *next;
} DL;

DL *createList(int *data, int n){
  DL *new;
  new = (DL *)malloc(sizeof(DL));
  int i;
  new->data = (int *)malloc(sizeof(int) * n);
  for(i=0; i<n; i++){
    new->data[i] = data[i];
  }
  new->num = n;

  return new;
}

void addList(DL **head, DL *add){
  add->next = *head;
  *head = add;
  return;
}

void deleteList(DL **pt){
  DL *del = *pt;
  *pt = del->next;

  free(del->data);
  free(del);
  return;
}

void printList(DL *head){
  int i, n, *data;
  puts("LIST---------------");
  while(head != NULL){
    n = head->num;
    data = head->data;
    for(i=0; i<n; i++) printf("%d ", data[i]);
    putchar('\n');
    head = head->next;
  }
  puts("---------------LIST");
  return;
}

int main()
{
  int M, N;
  int i, j, n, index, flg, find;
  int *ss;
  int data[100000]={0};
  int node[100000];

  DL *head=NULL;
  DL **search = NULL;
  scanf("%d%d", &N, &M);

  // 最初の人が喋れる言語のフラグを立てる。
  scanf("%d", &n);
  for(i=0; i<n; i++){
    scanf("%d", &index);
    data[index]++;
  }

  // 2番目以降の人の喋れる言語の入力
  // 同時に、すでにフラグの立ってる言語を喋れる場合、その人の喋れるすべての言語にフラグを立てる。
  // フラグが立ってない言語のみの場合はリストに保存する。
  for(i=1; i<N; i++){
    scanf("%d", &n);
    find=0;
    for(j=0; j<n; j++){
      scanf("%d", node+j);
      if(data[node[j]]) find++;
    }
    if(find){
      for(j=0; j<n; j++){
        data[node[j]]=1;
      }
    }else{
      DL *add = createList(node, n);
      addList(&head, add);
    }
  }

  // リストの探索で、喋れる言語がなくなるまでループする。
  // 新たに喋れる言語が見つからないとき(flg==0)か、リストのデータがなくなった時(head==NULL)にこのループを終了する。
  flg = 1;
  while(flg && head != NULL){
    search = &head;
    flg = 0;
    while(*search != NULL){
      n = (*search)->num;
      ss = (*search)->data;
      find=0;
      for(i=0; i<n; i++){
        if(data[ss[i]]) find++;
      }
      if(find){
        for(i=0; i<n; i++){
          data[ss[i]]=1;
        }
        deleteList(search);
        flg++;
      }else search = &(*search)->next;
    }
  }
  printf("%s\n", head==NULL?"YES":"NO");
  return(0);
}

