typedef struct{
    int par;
    int dep;
}node;

node uft[size];

void resuf(){
    int i;
    for(i=0;i<size;i++){
        uft[i].par=i;uft[i].dep=0;
    }
    return;
}

int find(int x){
    if(uft[x].par==x){return x;}
    else{uft[x].par=find(uft[x].par);return uft[x].par;}
}

void uni(int x,int y){
    int xp,yp;
    xp=find(x);yp=find(y);
    if(xp==yp){return;}
    if(uft[xp].dep>uft[yp].dep){
        uft[yp].par=xp;
    }
    else{
        uft[xp].par=yp;
        if(uft[xp].dep==uft[yp].dep){uft[yp].dep++;}
    }
    return;
}

