class UnionFind(val N: Int) {
    private val dt = IntArray(N+1){-1}
    fun root(key: Int): Int {
        return when {
            this.dt[key] < 0 -> {
                key
            }
            else -> {
                this.dt[key] = this.root(this.dt[key])
                this.dt[key]
            }
        }
    }
    fun unite(KX: Int, KY: Int): Boolean {
        val (rx, ry) = Pair(this.root(KX), this.root(KY))
        return when (rx) {
            ry -> {
                false
            }
            else -> {
                val (ky, kx) = if (this.size(ry) <= this.size(rx)) Pair(ry, rx)
                else Pair(rx, ry)
                this.dt[kx] += this.dt[ky]
                this.dt[ky] = kx
                true
            }
        }
    }
    fun size(key: Int): Int {
        val rk = this.root(key)
        return -this.dt[rk]
    }
    fun isConnect(kx: Int, ky: Int): Boolean {
        return this.root(kx) == this.root(ky)
    }
}

fun solve() {
    val (N, M) = rd.readListInt()
    val KL = rd.readListIntCols(N)

    val lgs = Array(N){mutableSetOf<Int>()}
    for (i in 0 until N) {
        lgs[i].addAll(KL[i].drop(1))
    }

    val uf = UnionFind(N)
    for (i in 0 until N) {
        for (j in i+1 until N) {
            if (uf.isConnect(i,j)) continue
            else if (lgs[i].intersect(lgs[j]).isNotEmpty()) {
                uf.unite(i,j)
            }
        }
    }

    val ans = if (uf.size(0)==N) "YES" else "NO"
    println(ans)

    return
}


