import java.util.ArrayDeque

fun main(args: Array<String>) {
    val (N, M) = readInputLine().split(" ").map { it.toInt() }

    // 言語番号 -> ノード番号のリスト
    val languageNodes = Array(M + 1) { mutableListOf<Int>() }

    val edges = Array(100000) { mutableListOf<Int>() }

    var currentNode = 0

    for (i in 1..N) {
        val languages = readInputLine().split(" ").map { it.toInt() }.drop(1).toIntArray()

        // 同じ参加者のノードをつなぐ
        for (j in 1 until languages.size) {
            edges[j + currentNode].add(j + currentNode - 1)
            edges[j + currentNode - 1].add(j + currentNode)
        }

        // 同じ言語のノードを覚えておく
        for ((index, l) in languages.withIndex()) {
            languageNodes[l].add(currentNode + index)
        }

        currentNode += languages.size
    }

    // 同じ言語のノードをつなぐ
    for (i in 1..M) {
        for (j in 1 until languageNodes[i].size) {
            edges[languageNodes[i][j - 1]].add(languageNodes[i][j])
            edges[languageNodes[i][j]].add(languageNodes[i][j - 1])
        }
    }

    // アクセス済みノード管理
    val used = BooleanArray(currentNode)
    val queue = ArrayDeque<Int>(currentNode)

    queue.add(0)
    used[0] = true

    while (queue.isNotEmpty()) {
        val n = queue.poll()!!
        for (e in edges[n]) {
            if (!used[e]) {
                queue.add(e)
                used[e] = true
            }
        }
    }

    if (used.count { it } == currentNode) {
        println("YES")
    } else {
        println("NO")
    }
}

