public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CInterpretation solver = new CInterpretation();
        solver.solve(1, in, out);
        out.close();
    }

    static class CInterpretation {
        public void solve(int testNumber, Scanner in, PrintWriter out) {

            int n = in.nextInt();
            int m = in.nextInt();
            UnionFindTree uf = new UnionFindTree(n);
            ArrayList<Integer>[] lang = new ArrayList[m];

            for (int i = 0; i < m; i++) {
                lang[i] = new ArrayList<>();
            }
            for (int i = 0; i < n; i++) {
                int k = in.nextInt();
                for (int j = 0; j < k; j++) {
                    lang[in.nextInt() - 1].add(i);
                }
            }
            for (int i = 0; i < m; i++) {
                for (int j = 1; j < lang[i].size(); j++) {
                    uf.union(lang[i].get(0), lang[i].get(j));
                }
            }


            for (int i = 1; i < n; i++) {
                if (!uf.same(0, i)) {
                    out.println("NO");
                    return;
                }
            }
            out.println("YES");

        }

    }

    static class UnionFindTree {
        private int[] parent;
        private int[] height;
        private int[] size;

        public UnionFindTree(int size) {
            this.parent = new int[size];
            this.height = new int[size];
            this.size = new int[size];

            for (int i = 0; i < size; i++) {
                makeSet(i);
            }
        }

        private void makeSet(int i) {
            parent[i] = i;
            height[i] = 0;
            size[i] = 1;
        }

        public int find(int x) {
            if (x != parent[x]) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {

            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) { //既に結合済み
                return;
            }

            if (height[rootX] > height[rootY]) {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];

            } else if (height[rootX] < height[rootY]) {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];

            } else {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
                height[rootX]++;
            }
        }

        public boolean same(int x, int y) {
            return find(x) == find(y);
        }

    }
}

