import java.io.*;
import java.util.*;

class UnionFind{
	int node[];
	UnionFind(int n){
		node = new int[n];
		Arrays.fill(node, -1);
	}

	int size(int x) {
		return -node[root(x)];
	}

	boolean same(int x, int y) {
		return root(x) == root(y);
	}

	void unite(int x, int y) {
		if(same(x, y))return;
		if(size(x) > size(y)) {
			unite(y, x);
			return;
		}
		int rx = root(x), ry = root(y);
		node[ry] += node[rx];
		node[rx] = ry;
	}

