        } else {
            System.out.println("NO");
        }
    }
    class UnionFind {
        private int[] parent;
        private int[] size;
        UnionFind(int N) {
            int[] parent = new int[N];
            for (int i = 0; i < N; i++) {
                parent[i] = i;
            }
            int[] size = new int[N];
            Arrays.fill(size, 1);
            this.parent = parent;
            this.size = size;
        }
        int find(int x) {
            if (x == this.parent[x]) {
                return x;
            }
            return this.parent[x] = find(this.parent[x]);
        }
        boolean same(int x, int y) {
            return find(x) == find(y);
        }
        void unite(int x, int y) {
            int parent_x = find(x);
            int parent_y = find(y);
            if (parent_x == parent_y) {
                return;
            }
            int size_x = this.size[parent_x];
            int size_y = this.size[parent_y];
            if (size_x < size_y) {
                this.size[parent_y] += this.size[parent_x];
                this.parent[parent_x] = parent_y;
                this.size[parent_x] = -1;
                return;
            }
            this.size[parent_x] += this.size[parent_y];
            this.parent[parent_y] = parent_x;
            this.size[parent_y] = -1;
        }
        int size(int x) {
            int parent_x = find(x);
            return this.size[parent_x];
        }
    }
}

