    static int[] id;
    public static void main(String[] args)throws IOException{
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt();
        boolean[] used = new boolean[M+1];
        id = new int[M+1];
        for(int i=0;i<=M;i++) id[i]=i;
        int l0 = 0;
        for(int i=0;i<N;i++){
            int k = sc.nextInt();
            l0 = sc.nextInt();
            used[l0] = true;
            for(int j=1;j<k;j++){
                int lj = sc.nextInt();
                used[lj]=true;
                union(lj,l0);
            }
        }
        int root = find(l0);
        boolean ans = true;
        for(int i=1;i<=M;i++){
            if(!used[i]) continue;
            ans &= find(i)==root;
        }
        String res = ans?"YES":"NO";
        System.out.println(res);
    }
    static int find(int p){
        while(id[p]!=p){
            id[p] = id[id[p]];
            p = id[p];
        }
        return id[p];
    }
    static void union(int p, int q){
        int i=find(p), j=find(q);
        if(i==j) return;
        id[j]=i;
    }
}

import java.util.*;

public class Main {
  static int[] par;
  static int[] rank;
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int m = sc.nextInt();
    par = new int[n];
    rank = new int[n];
    ArrayList[] list = new ArrayList[m];
    for(int i = 0; i < m; i++) {
      list[i] = new ArrayList<Integer>();
    }
    for(int i = 0; i < n; i++) {
      int k = sc.nextInt();
      for(int j = 0; j < k; j++) {
        int l = sc.nextInt() - 1;
        list[l].add(i);
      }
    }
    init(n);
    for(int i = 0; i < m; i++) {
      for(int j = 0; j < list[i].size() - 1; j++) {
        unite((int)list[i].get(j), (int)list[i].get(j + 1));
      }
    }
    String ans = "NO";
    HashSet<Integer> set = new HashSet<Integer>();
    for(int i = 0; i < n; i++) {
      set.add(find(i));
    }
    if(set.size() == 1) ans = "YES";
    System.out.println(ans);
  }
  static void init(int m) {
      for(int i = 0; i < m; i++) {
        par[i] = i;
        rank[i] = 0;
      }
    }
  static int find(int x) {
      if(par[x] == x) {
        return x;
      } else {
        return par[x] = find(par[x]);
      }
    }
  static void unite(int x, int y) {
      x = find(x);
      y = find(y);
      if(x != y) {
        if(rank[x] < rank[y]) {
          par[x] = y;
        } else {
          par[y] = x;
          if(rank[x] == rank[y]) {
            rank[x]++;
          }
        }
      }
    }
  static boolean same(int x, int y) {
      return find(x) == find(y);
    }
}

