class UnionFind { // N=numNode
	int n;
	int parent[];
	int size[];

	UnionFind(int n) { // O(N)
		nonNegativeCheck(n);
		this.n = n;
		parent = new int[n];
		size = new int[n];
		for(int i = 0; i < n; i ++) initNode(i);
	}

	void initNode(int i) { // O(1)
		rangeCheck(i, n);
		parent[i] = i;
		size[i] = 1;
	}

	void unite(int x, int y) { // O(ﾎｱ(N))
		rangeCheck(x, n);
		rangeCheck(y, n);
		int xRoot = root(x);
		int yRoot = root(y);
		if(xRoot == yRoot) return;
		if(size[yRoot] > size[xRoot]) {
			parent[xRoot] = yRoot;
			size[yRoot] += size[xRoot];
		}else {
			parent[yRoot] = xRoot;
			size[xRoot] += size[yRoot];
		}
	}

	int size(int i) { rangeCheck(i, n); return size[root(i)]; } // O(ﾎｱ(N))

	int root(int i) { // O(ﾎｱ(N))
		rangeCheck(i, n);
		if(i != parent[i]) parent[i] = root(parent[i]);
		return parent[i];
	}

	boolean same(int x, int y) { rangeCheck(x, n); rangeCheck(y, n); return root(x) == root(y); } // O(ﾎｱ(N))

	HashMap<Integer, ArrayList<Integer>> groups() { // O(N)
		HashMap<Integer, ArrayList<Integer>> groups = new HashMap<>();
		for(int i = 0; i < n; i ++) {
			int root = root(i);
			if(!groups.containsKey(root)) groups.put(root, new ArrayList<>());
			groups.get(root).add(i);
		}
		return groups;
	}
}

	}
}

