	static void union(int x, int y)
	{
		int rx = root(x);
		int ry = root(y);

		if(rank[rx] >= rank[ry])
		{
			par[ry] = rx;
			if(rank[rx] == rank[ry])
				rank[rx]++;
		}
		else par[rx] = ry;
	}

	static int root(int x)
	{
		if(par[x] != x)
			par[x] = root(par[x]);
