        {
            int visitNum = 1;
            c[s] = 1;
            q.Enqueue(s);

            while(q.Count >= 1)
            {
                var u = q.Dequeue();

                var list = g[u];
                foreach(var v in list)
                {
                    if( c[v] != 0) { continue; }
                    c[v] = 1;
                    visitNum++;
                    q.Enqueue(v);
                }
