			rank = new int[N];
			for (int i = 0; i < N; i++)
			{
				parent[i] = i;
			}
		}

		public int find(int x)
		{
			if (parent[x] == x)
			{
				return x;
			}
			else
			{
				return parent[x] = find(parent[x]);
			}
		}

		public void unite(int x, int y)
		{
			x = find(x);
			y = find(y);
			if (rank[x] < rank[y])
			{
				parent[x] = y;
			}
			else
			{
				parent[y] = x;
				if (rank[x] == rank[y]) rank[x]++;
			}
		}

