			var uf = new UnionFindTree(m);
			for (int i = 0; i < n; i++) {
				var kl = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
				int s = kl[0];
				for (int j = 1; j <= s - 1; j++) {
					uf.TryUnite(kl[j] - 1, kl[j + 1] - 1);
				}

				for (int j = 1; j <= s; j++) {
					hash.Add(kl[j] - 1);
				}
			}

			int parent = - 1;
			for (int i = 0; i < m; i++) {
				if (hash.Contains(i)) {
					if (parent == -1) {
						parent = uf.Find(i);
					} else {
						if (parent != uf.Find(i)) {
