	public class UnionFindTree
	{
		private int[] sizes_;
		private int[] parent_;
		public int TreeCount { get; set; }

		public UnionFindTree(int n)
		{
			parent_ = new int[n];
			sizes_ = new int[n];
			for (int i = 0; i < n; i++) {
				parent_[i] = i;
				sizes_[i] = 1;
			}

			TreeCount = n;
		}

		public int Find(int x)
		{
			while (parent_[x] != x) {
				parent_[x] = parent_[parent_[x]];
				x = parent_[x];
			}

			return x;
		}

		public bool IsUnited(int x, int y)
		{
			return Find(x) == Find(y);
		}

		public void TryUnite(int x, int y)
		{
			int rootX = Find(x);
			int rootY = Find(y);
			if (rootX == rootY) {
				return;
			}

			int sizeX = sizes_[rootX];
			int sizeY = sizes_[rootY];
			if (sizeX < sizeY) {
				parent_[rootX] = rootY;
				sizes_[rootY] += sizeX;
			} else {
				parent_[rootY] = rootX;
				sizes_[rootX] += sizeY;
			}

			--TreeCount;
		}
	}
}

