class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var M = sc.ReadInt();
        var speaker = new List<int>[M];
        for (int i = 0; i < M; i++)
        {
            speaker[i] = new List<int>();
        }
        for (int i = 0; i < N; i++)
        {
            var K = sc.ReadInt();
            for (int j = 0; j < K; j++)
            {
                var l = sc.ReadInt() - 1;
                speaker[l].Add(i);
            }
        }
        var uf = new UnionFind(N);
        for (int i = 0; i < M; i++)
        {
            for (int j = 0; j < speaker[i].Count - 1; j++)
            {
                uf.Union(speaker[i][j], speaker[i][j + 1]);
            }
        }
        var ok = uf.Size(0) == N;
        Console.WriteLine(ok ? "YES" : "NO");
    }

    class UnionFind
    {
        public int[] Parents;
        public int[] Rank;
        public UnionFind(int n)
        {
            this.Parents = Enumerable.Repeat(-1, n).ToArray();
            this.Rank = new int[n];
        }
        public int Find(int x)
        {
            if (this.Parents[x] < 0) return x;
            this.Parents[x] = Find(this.Parents[x]);
            return this.Parents[x];
        }
        public int Size(int x)
        {
            return -this.Parents[this.Find(x)];
        }
        public bool Same(int x, int y)
        {
            return this.Find(x) == this.Find(y);
        }
        public bool Union(int x, int y)
        {
            x = this.Find(x);
            y = this.Find(y);
            if (x == y) return false;

            if (this.Rank[x] < this.Rank[y])
            {
                var tmp = x;
                x = y;
                y = tmp;
            }
            if (this.Rank[x] == this.Rank[y]) this.Rank[x]++;
            this.Parents[x] += this.Parents[y];
            this.Parents[y] = x;
            return true;
        }
        public int GetGroupCount()
        {
            return this.Parents.Count(p => p < 0);
        }
    }
    static Scanner sc = new Scanner();
}
