            Multi(out N, out M);
            var G = new Dictionary<int, List<int>>();
            for (int i = 0; i < N + M; i++) G.Add(i, new List<int>());
            for(int i = 0; i < N; i++)
            {
                foreach(var l in GetIntArray().Skip(1))
                {
                    G[i].Add(l-1);
                    G[N + l-1].Add(i);
                }   
            }

            var dist = new int[N+M].Select(s => -1L).ToArray();
            var queue = new Queue<int>();
            dist[0] = 0;
            queue.Enqueue(0);
            while (queue.Count() > 0)
            {
                var now = queue.Dequeue();
                foreach (var next in G[now])
                {
                    if (dist[next] != -1) continue;
                    dist[next] = dist[now] + 1;
                    queue.Enqueue(next);
                }
            }
            dist.Take(N).All(a => a!=-1).YESNO();
        }
