class Program
{
    private static int N;
    private static int M;
    private static int[][] L;

    public static void Main()
    {
        /*入力を受け取る*/
        int[] inputs = Console.ReadLine().Split().Select(int.Parse).ToArray();
        N = inputs[0];
        M = inputs[1];
        L = new int[N][];
        for (int i = 0; i < N; i++)
        {
            inputs = Console.ReadLine().Split().Select(int.Parse).ToArray();
            L[i] = new int[inputs[0]];
            for (int j = 1; j <= inputs[0]; j++)
                L[i][j - 1] = inputs[j] - 1; //言語の番号は0～M-1に変更
        }

        /*どの言語間でコミュニケーションがとれるか、言語をノードとするUnionFind
           を用いて整理する。*/
        UF uf = new UF(M);
        foreach (var l in L) //各参加者について
            for (int i = 0; i < l.Length - 1; i++)
                uf.Unite(l[i], l[i + 1]); //その人の話せる言語を統合

        /*参加者iとi+1の話せる言語が同じ木に属するか、で判定*/
        for (int i = 0; i < N - 1; i++)
        {
            if (uf.Same(L[i][0], L[i + 1][0]))
                continue;
            Console.WriteLine("NO");
            return;
        }
        Console.WriteLine("YES");
    }
}

namespace UnionFind
{
    class UF
    {
        private int[] 親; //親[i] : iの親の番号

        public UF(int N) //コンストラクタ、すべてが根として初期化
        {
            親 = new int[N];
            for (int i = 0; i < N; i++)
                親[i] = i;
        }

        public int Root(int x) //xの属する木の根を返す
        {
            if (親[x] == x) return x;
            return 親[x] = Root(親[x]);
        }

        public void Unite(int x, int y) //xとyの木を統合
        {
            int rx = Root(x);
            int ry = Root(y);
            if (rx == ry) return;
            親[rx] = ry;
        }

        public bool Same(int x, int y) //xとyが同じ木に属するかどうかを返す
        {
            return Root(x) == Root(y);
        }
    }
}

