const maxSize = 100000

var data [maxSize + 1]map[int]bool

func main() {
	var n, m int
	scan(&n, &m)

	// init
	for i := 1; i <= n; i++ {
		uf[i] = i
	}
	ufGroupSize = n
	for i := 1; i <= m; i++ {
		data[i] = map[int]bool{}
	}

	for i := 1; i <= n; i++ {
		var x int
		scan(&x)
		for z := 0; z < x; z++ {
			var t int
			scan(&t)
			data[t][i] = true
		}
	}

	// solve
	for i := 1; i <= m; i++ {
		l := -1
		for v := range data[i] {
			if l != -1 {
				merge(v, l)
			}
			l = v
		}
	}

	// out
	if ufGroupSize == 1 {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

var uf [maxSize + 1]int
var ufGroupSize int

func merge(x, y int) {
	px, py := parent(x), parent(y)
	if px == py {
		return
	}
	ufGroupSize--
	uf[py] = px
}

func parent(x int) int {
	for uf[x] != x {
		x, uf[x] = uf[x], uf[uf[x]]
	}
	return x
}

