// UnionFind木
struct UnionFindTree
{
	private long[] ps;
	private long[] rs;

	public this( long n )
	{
		ps.length = n;
		ps[] = -1;
		rs.length = n;
	}

	public long root( long i )
	{
		if( ps[ i ] < 0 ) return i;
		else              return ps[ i ] = root( ps[ i ] );
	}

	public bool same( long i, long j )
	{
		return root( i ) == root( j );
	}

	public void unite( long i, long j )
	{
		i = root( i );
		j = root( j );
		if( i == j ) return;
		if( rs[ i ] < rs[ j ] )
		{
			ps[ j ] += ps[ i ];
			ps[ i ] = j;
		}
		else
		{
			ps[ i ] += ps[ j ];
			ps[ j ] = i;
			if( rs[ i ] == rs[ j ] ) rs[ i ]++;
		}
	}
}

