class UnionFind:
    def __init__(self, n):
        self.v = [-1 for _ in range(n)]
        # 負:=連結頂点数, 自身が根
        # 正:=親index, 0-indexed

    def is_root(self, x):
        return self.v[x] < 0

    def find(self, x):
        if self.v[x] < 0:
            return x
        else:
            self.v[x] = self.find(self.v[x])
            return self.v[x]

    def is_same(self, x, y):
        return self.find(x) == self.find(y)

    def merge(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return

        if -self.v[x] < -self.v[y]:
            x, y = y, x
        # x を連結頂点数最大にする

        self.v[x] += self.v[y]
        self.v[y] = x

    def get_size(self, x):
        x = self.find(x)
        return -self.v[x]


