    let mut buf_it = buf.split_whitespace();

    let N = buf_it.next().unwrap().parse::<usize>().unwrap();
    let M = buf_it.next().unwrap().parse::<usize>().unwrap();

    let mut K = vec![0;N];
    let mut L = vec![Vec::new();N];

    for i in 0..N{
        K[i] = buf_it.next().unwrap().parse::<usize>().unwrap();
        for _ in 0..K[i]{
