        }
    }

    let mut E = vec![Vec::new();N+M];
    for i in 0..N{
        for j in 0..K[i]{
            E[i].push(L[i][j]+N);
            E[L[i][j]+N].push(i);
        }
    }

    let c = dfs_connect(N+M,E,0);

    let mut ans = true;
    for i in 0..N{
        ans &= c[i];
    }

    println!("{}",if ans {"YES"} else {"NO"});
}

fn dfs_connect(N:usize,E:Vec<Vec<usize>>,start:usize) -> Vec<bool>{
    let mut done = vec![false;N];
    let mut q = vec![start];
    while let Some(i) = q.pop(){
        for &j in &E[i]{
            if done[j] {continue;}
            q.push(j);
            done[j] = true;
        }
    }
    done
}

