struct UnionFind {
    parent: Option<usize>,
    size: u32,
}

impl Clone for UnionFind {
    fn clone(&self) -> Self {
        UnionFind {
            parent: self.parent.clone(),
            size: self.size,
        }
    }
}

fn root(a: usize, uf: &mut Vec<UnionFind>) -> usize {
    if let Some(v) = uf[a].parent {
        let tmp = root(v, uf);
        uf[a].parent = Some(tmp);
        tmp
    } else {
        a
    }
}

fn union(a: usize, b: usize, uf: &mut Vec<UnionFind>) {
    let ar = root(a, uf);
    let br = root(b, uf);
    if ar == br {
        return;
    }
    if uf[ar].size >= uf[br].size {
        uf[ar].size += uf[br].size;
        uf[br].parent = Some(ar);
    } else {
        uf[br].size += uf[ar].size;
        uf[ar].parent = Some(br);
    }
}

