fn solve() {
    let (n,m) = get!(usize, usize);
    let kl = get!([usize]; n);

    let mut nodes = vec![Vec::new(); n+m+2];
    for i in 0..n {
        for &l in kl[i].iter().skip(1) {
            nodes[i+1].push(n+l);
            nodes[n+l].push(i+1);
        }
    }

    let mut queue = VecDeque::new();
    let mut visited = vec![false; n+m+2];
    queue.push_back(1);
    visited[1] = true;
    while let Some(node) = queue.pop_front() {
        for &next in &nodes[node] {
            if visited[next] {
                continue;
            }
            queue.push_back(next);
            visited[next] = true;
        }
    }
    for i in 1..n+1 {
        if !visited[i] {
            println!("NO");
            return;
        }
    }
    println!("YES");
}

