fn find(v:&mut Vec<usize>, x: usize) -> usize{
    let p = v[x];
    if p == x{
        return x
    }
    let a = find(v,p);
    v[x] = a;
    a
}

fn union(v:&mut Vec<usize>, x:usize, y:usize) {
    let bx: usize;
    let by: usize;

    if find(v, x) > find(v,y) {
        bx = find(v,y);
        by = find(v,x);
    }else{
        bx = find(v,x);
        by = find(v,y);
    }
    v[y] = bx;
    v[by] = bx;
}


